/* ОГЭ 2027: v35 · 12 авторских тем, 432 задания, поверх v34.
 * Существующие идентификаторы тем, ключи прогресса, Supabase и дневник не изменены. */
(()=>{'use strict';
 const reference=window.OGE_GRAMMAR_REFERENCE_V18,program=window.OGE_PROGRAM;
 if(!reference?.guides||!program?.grammarGroups){console.error('v35: required module is missing');return;}
 const chapters={"Can и could":{"slug":"g5t1","theory":"<article class=\"gm35 gm35-topic-1\" id=\"rule-theory\" lang=\"ru\"><header><small>МОДАЛЬНОСТЬ · УМЕНИЕ И ВОЗМОЖНОСТЬ</small><h2>Can и could: что возможно, что умеем и что было возможно?</h2><p>Одна форма <b>can</b> служит нескольким целям. Не начинай с перевода «могу»: выясни, о способности, разрешении или реальной возможности говорит автор.</p></header>\n<section><h3>Три смысла, разные ситуации</h3><div class=\"gm35-grid\"><article><b>Способность</b><p>My sister <b>can swim</b>. — Моя сестра умеет плавать.</p></article><article><b>Возможность в обстоятельствах</b><p>You <b>can buy</b> tickets online. — Билеты можно купить онлайн.</p></article><article><b>Разрешение</b><p><b>Can</b> I leave early? — Можно мне уйти пораньше?</p></article></div><p>В прошедшем <b>could</b> часто обозначает общую способность: She <b>could read</b> at five. — В пять лет она умела читать. Но для <em>одного успешно совершённого действия</em> в конкретной ситуации чаще подходит <b>managed to / was able to</b>: We <b>managed to find</b> the keys. — Нам удалось найти ключи.</p></section>\n<section><h3>Грамматическая конструкция</h3><div class=\"gm35-formula\">Подлежащее + can / could + <b>V1 без to</b></div><div class=\"gm35-table\"><table><tr><th>Утверждение</th><th>Отрицание</th><th>Вопрос</th></tr><tr><td>She can drive.<small>Она умеет водить.</small></td><td>She can't drive.<small>Она не умеет водить.</small></td><td>Can she drive?<small>Она умеет водить?</small></td></tr></table></div><p>После <b>can</b> никогда не появляется <b>-s</b> или <b>to</b>: He <b>can play</b>, не <s>cans plays</s>. Краткий ответ: Yes, he can / No, he can't.</p></section>\n<section><h3>Could — не только прошедшее время</h3><p>Could you open the window? — Не могли бы вы открыть окно? Это <b>вежливая просьба сейчас</b>, а не описание прошлого. We could go by train. — Мы могли бы поехать поездом (предложение). <b>Could</b> может выражать менее уверенную возможность: It could rain later. — Возможно, позже пойдёт дождь.</p><div class=\"gm35-error\"><s>She can to speak Italian.</s><b>She can speak Italian.</b><small>После модального глагола используется инфинитив без to.</small></div><div class=\"gm35-error\"><s>Did you could swim?</s><b>Could you swim?</b><small>Вопрос с could строится без did.</small></div></section>\n<section><h3>Алгоритм для ОГЭ</h3><ol><li>Определи время и значение: способность, разрешение, возможность, просьба?</li><li>Для общей способности в прошлом рассмотри <b>could</b>; для разового успешного результата — <b>was/were able to</b>.</li><li>Не добавляй <b>to</b> после can/could.</li><li>Проверь, не является ли could вежливой просьбой в настоящем.</li></ol></section></article>","levels":[[{"id":"v35-g5t1-0-1","prompt":"My younger brother ___ ride a bike now. (ability)","answer":"can","why":"Речь об умении сейчас.","options":["can","could","can't","must"]},{"id":"v35-g5t1-0-2","prompt":"At six, Lena ___ already read in English. (past general ability)","answer":"could","why":"Устойчивое умение в прошлом: could.","options":["can't","must","may","could"]},{"id":"v35-g5t1-0-3","prompt":"___ you help me with this bag, please? (polite request)","answer":"Could","why":"Could выражает вежливую просьбу.","options":["may","might","Could","must"]},{"id":"v35-g5t1-0-4","prompt":"I ___ go to the cinema tonight: I have a ticket and free time. (present opportunity; use CAN)","answer":"can","why":"Возможность в сложившихся обстоятельствах.","options":["Could","can","may","might"]},{"id":"v35-g5t1-0-5","prompt":"My grandad ___ play the piano when he was young.","answer":"could","why":"Общее умение в молодости.","options":["could","might","Can","can"]},{"id":"v35-g5t1-0-6","prompt":"___ I use your phone for a second? (informal permission)","answer":"Can","why":"Просьба разрешить действие себе.","options":["Could","could","can't","Can"]},{"id":"v35-g5t1-0-7","prompt":"No, you ___ park here. The sign says PRIVATE.","answer":"can't","why":"Отрицательное can обозначает отсутствие разрешения.","options":["can","could","can't","Can"]},{"id":"v35-g5t1-0-8","prompt":"Mira ___ run very fast now, but she can't swim.","answer":"can","why":"Противопоставлены два умения.","options":["may","can","can't","must"]},{"id":"v35-g5t1-0-9","prompt":"When I lived in the village, I ___ see stars clearly.","answer":"could","why":"В прошлом была постоянная возможность.","options":["could","must","may","might"]},{"id":"v35-g5t1-0-10","prompt":"It ___ snow tonight, so take a coat. (uncertain possibility; use COULD)","answer":"could","why":"Could допускает возможность, не утверждая факт.","options":["may","might","Can","could"]},{"id":"v35-g5t1-0-11","prompt":"He ___ speak three languages fluently now.","answer":"can","why":"Умеет говорить сейчас.","options":["Could","could","can","might"]},{"id":"v35-g5t1-0-12","prompt":"___ you open the door for me? (use COULD)","answer":"Could","why":"Вежливая просьба: Could you + V1.","options":["can't","Could","Can","can"]}],[{"id":"v35-g5t1-1-1","prompt":"Make negative: She can ski.","answer":"She can't ski.||She cannot ski.","why":"Отрицание can = cannot / can't.","options":null},{"id":"v35-g5t1-1-2","prompt":"Make a question: They can speak Polish.","answer":"Can they speak Polish?","why":"Can ставим перед подлежащим.","options":null},{"id":"v35-g5t1-1-3","prompt":"Correct: My brother cans drive.","answer":"My brother can drive.","why":"У модального can нет -s.","options":null},{"id":"v35-g5t1-1-4","prompt":"Correct: Could you to wait here?","answer":"Could you wait here?","why":"После could не ставим to.","options":null},{"id":"v35-g5t1-1-5","prompt":"Rewrite with COULD (past ability): I was good at swimming at age seven.","answer":"I could swim well at age seven.","why":"Could описывает общую способность в прошлом.","options":null},{"id":"v35-g5t1-1-6","prompt":"Correct: Did you could read then?","answer":"Could you read then?","why":"С модальным could не нужен did.","options":null},{"id":"v35-g5t1-1-7","prompt":"Write short answer YES: Can she help?","answer":"Yes, she can.","why":"Полный вспомогательный глагол в коротком ответе.","options":null},{"id":"v35-g5t1-1-8","prompt":"Write short answer NO: Could he ride a bike at five?","answer":"No, he couldn't.||No, he could not.","why":"Could not = couldn't.","options":null},{"id":"v35-g5t1-1-9","prompt":"Correct: They can to use the library.","answer":"They can use the library.","why":"После can начальная форма без to.","options":null},{"id":"v35-g5t1-1-10","prompt":"Change into a question: You could hear the sea from your room.","answer":"Could you hear the sea from your room?","why":"Could переносим перед you.","options":null},{"id":"v35-g5t1-1-11","prompt":"Correct: He doesn't can cook.","answer":"He can't cook.||He cannot cook.","why":"У can собственная форма отрицания.","options":null},{"id":"v35-g5t1-1-12","prompt":"Rewrite using CAN: It is possible to buy the tickets online.","answer":"You can buy the tickets online.","why":"Возможность в обстоятельствах выражается can.","options":null}],[{"id":"v35-g5t1-2-1","prompt":"Before the trip, I ___ (CAN) swim, but I was afraid of deep water. [past ability]","answer":"could","why":"Для общей способности в прошлом could.","options":null},{"id":"v35-g5t1-2-2","prompt":"My sister isn't at home, but I ___ (CAN) call her later. [current possibility]","answer":"can","why":"Настоящая возможность: can.","options":null},{"id":"v35-g5t1-2-3","prompt":"Our guide was ill, but we ___ (MANAGE) find the hotel on our own. [one successful action; write 2 words]","answer":"managed to","why":"Разовый успешный результат: managed to.","options":null},{"id":"v35-g5t1-2-4","prompt":"In the old house, we ___ (CAN) hear the trains every night.","answer":"could","why":"Устойчивое ощущение/возможность в прошлом.","options":null},{"id":"v35-g5t1-2-5","prompt":"At the airport, security said we ___ (CAN / NOT) take liquids on board. [one word]","answer":"couldn't","why":"Запрет/невозможность в прошлом: couldn't take.","options":null},{"id":"v35-g5t1-2-6","prompt":"Could you ___ (EXPLAIN) this sign to me?","answer":"explain","why":"После could инфинитив без to.","options":null},{"id":"v35-g5t1-2-7","prompt":"When the storm ended, we ___ (BE ABLE) leave the village. [past, 3 words]","answer":"were able to","why":"Конкретная возможность после шторма: were able to.","options":null},{"id":"v35-g5t1-2-8","prompt":"My cousin ___ (CAN) draw well, but she isn't good at singing.","answer":"can","why":"Способность сейчас.","options":null},{"id":"v35-g5t1-2-9","prompt":"We ___ (CAN) visit the museum tomorrow; it's free.","answer":"can","why":"Доступная возможность завтра: can допустимо.","options":null},{"id":"v35-g5t1-2-10","prompt":"If you ___ (CAN) come early, we can practise together. [use CAN]","answer":"can","why":"Условное предложение с возможностью.","options":null},{"id":"v35-g5t1-2-11","prompt":"It ___ (COULD) be a mistake; let's check the figures.","answer":"could","why":"Could выражает предположение.","options":null},{"id":"v35-g5t1-2-12","prompt":"The child ___ (CAN) read at four, although nobody had taught him formally.","answer":"could","why":"Общая способность в прошлом.","options":null}]]},"Be able to":{"slug":"g5t2","theory":"<article class=\"gm35 gm35-topic-2\" id=\"rule-theory\" lang=\"ru\"><header><small>МОДАЛЬНОСТЬ · ВРЕМЯ И РЕЗУЛЬТАТ</small><h2>Be able to: способность там, где can не хватает</h2><p>Конструкция <b>be able to + V1</b> позволяет говорить об умении в разных временах. Выбор формы зависит от <b>be</b>, а не от смыслового глагола.</p></header>\n<section><h3>Лестница времён</h3><div class=\"gm35-flow\"><span>am/is/are able to<br><small>сейчас</small></span><span>was/were able to<br><small>прошлое</small></span><span>will be able to<br><small>будущее</small></span><span>have/has been able to<br><small>опыт до сейчас</small></span></div><p>I <b>am able to</b> work independently. — Я способна работать самостоятельно. We <b>will be able to</b> join tomorrow. — Завтра мы сможем присоединиться. She <b>has been able to</b> walk since the operation. — После операции она может ходить.</p></section>\n<section><h3>Общая способность vs единичный успех</h3><div class=\"gm35-grid two\"><article><b>Общее умение в прошлом</b><p>At ten, Tom <b>could swim</b>. — В десять Том умел плавать.</p></article><article><b>Успех в конкретной ситуации</b><p>Despite the storm, we <b>were able to get</b> home. — Несмотря на шторм, мы смогли добраться домой.</p></article></div><p>Для разового <em>успешного</em> действия употребляй <b>was/were able to</b> или <b>managed to</b>; в отрицании <b>couldn't</b> часто подходит для невозможности конкретного действия: We couldn't get home.</p></section>\n<section><h3>Формы и ловушки</h3><div class=\"gm35-table\"><table><tr><th>Тип</th><th>Пример</th></tr><tr><td>Отрицание</td><td>He <b>wasn't able to</b> come. — Он не смог прийти.</td></tr><tr><td>Вопрос</td><td><b>Will</b> you <b>be able to</b> help? — Ты сможешь помочь?</td></tr><tr><td>После модального</td><td>You <b>must be able to</b> explain it. — Нужно уметь это объяснить.</td></tr></table></div><p><b>To</b> — обязательная часть be able <b>to</b>. Нельзя сказать <s>will can</s>: вместо этого <b>will be able to</b>.</p><div class=\"gm35-error\"><s>I will can join.</s><b>I will be able to join.</b><small>После will используют be able to, а не can.</small></div><div class=\"gm35-error\"><s>We will can join tomorrow.</s><b>We will be able to join tomorrow.</b><small>Will can не существует: вместо can после will используется be able to.</small></div><p>Для конкретной ситуации, где умение не доказано успехом, сравни: I could solve such problems then (общее умение) / I was able to solve that problem (решил конкретную).</p></section></article>","levels":[[{"id":"v35-g5t2-0-1","prompt":"After months of practice, I am ___ to swim 500 metres.","answer":"able","why":"Be able to + V1.","options":["able","was","were","will"]},{"id":"v35-g5t2-0-2","prompt":"She ___ able to finish the race yesterday.","answer":"was","why":"Одна ученица: was able to.","options":["were","will","been","was"]},{"id":"v35-g5t2-0-3","prompt":"They ___ be able to travel next summer.","answer":"will","why":"Будущая возможность: will be able to.","options":["been","to","will","were"]},{"id":"v35-g5t2-0-4","prompt":"We weren't able ___ open the old door.","answer":"to","why":"Внутри конструкции всегда able to.","options":["are","to","will","been"]},{"id":"v35-g5t2-0-5","prompt":"___ you be able to join the video call tomorrow?","answer":"Will","why":"Вопрос о будущем: Will you be able to...?","options":["Will","to","are","be"]},{"id":"v35-g5t2-0-6","prompt":"He has ___ able to walk without help since June.","answer":"been","why":"Present Perfect: has been able to.","options":["are","be","able","been"]},{"id":"v35-g5t2-0-7","prompt":"I ___ not able to find the documents last night.","answer":"was","why":"I + was not able to.","options":["able","were","was","be"]},{"id":"v35-g5t2-0-8","prompt":"Students ___ able to borrow books from this library. (present)","answer":"are","why":"Students: are able to.","options":["were","are","able","was"]},{"id":"v35-g5t2-0-9","prompt":"I ___ be able to help on Friday. (future)","answer":"will","why":"После will употребляем be able to.","options":["will","was","were","been"]},{"id":"v35-g5t2-0-10","prompt":"My phone died, but I ___ able to send one message before it did.","answer":"was","why":"Разовый успешный результат: was able to.","options":["will","been","to","was"]},{"id":"v35-g5t2-0-11","prompt":"___ she able to solve the puzzle in the end? (past)","answer":"Was","why":"Past question with be before she.","options":["to","are","Was","been"]},{"id":"v35-g5t2-0-12","prompt":"We might ___ able to leave early.","answer":"be","why":"После might: be able to.","options":["are","be","been","to"]}],[{"id":"v35-g5t2-1-1","prompt":"Correct: I'll can come later.","answer":"I'll be able to come later.||I will be able to come later.","why":"После will нельзя ставить can.","options":null},{"id":"v35-g5t2-1-2","prompt":"Make negative: He was able to drive.","answer":"He wasn't able to drive.||He was not able to drive.","why":"Отрицание ставим после was.","options":null},{"id":"v35-g5t2-1-3","prompt":"Make a question: She will be able to help.","answer":"Will she be able to help?","why":"Will + she + be able to.","options":null},{"id":"v35-g5t2-1-4","prompt":"Correct: They are able speak Italian.","answer":"They are able to speak Italian.","why":"To обязательно.","options":null},{"id":"v35-g5t2-1-5","prompt":"Transform to past: We are able to see the sea.","answer":"We were able to see the sea.","why":"We + were в Past Simple.","options":null},{"id":"v35-g5t2-1-6","prompt":"Use HAVE BEEN: She is able to work again. [start with She has]","answer":"She has been able to work again.","why":"Present Perfect: has been able to.","options":null},{"id":"v35-g5t2-1-7","prompt":"Correct: Was she able solve it?","answer":"Was she able to solve it?","why":"Не пропускаем to.","options":null},{"id":"v35-g5t2-1-8","prompt":"Use WILL BE ABLE TO: I can finish it next week.","answer":"I will be able to finish it next week.","why":"У will нет сочетания с can.","options":null},{"id":"v35-g5t2-1-9","prompt":"Make a question: They were able to catch the train.","answer":"Were they able to catch the train?","why":"Вопрос с were перед they.","options":null},{"id":"v35-g5t2-1-10","prompt":"Correct: He didn't was able to leave.","answer":"He wasn't able to leave.||He was not able to leave.","why":"Для be используется отрицание wasn't, без did.","options":null},{"id":"v35-g5t2-1-11","prompt":"Rewrite using WAS ABLE TO: She succeeded in opening the safe.","answer":"She was able to open the safe.","why":"Единичный достигнутый результат.","options":null},{"id":"v35-g5t2-1-12","prompt":"Make negative: We will be able to join.","answer":"We won't be able to join.||We will not be able to join.","why":"После won't остаётся be able to.","options":null}],[{"id":"v35-g5t2-2-1","prompt":"After the power returned, we ___ (BE ABLE TO) finish the online lesson. [past, 3 words]","answer":"were able to","why":"Разовый успех во множественном числе.","options":null},{"id":"v35-g5t2-2-2","prompt":"In a few years, the twins ___ (BE ABLE TO) speak two foreign languages. [future, 4 words]","answer":"will be able to","why":"В будущем: will be able to.","options":null},{"id":"v35-g5t2-2-3","prompt":"The mountain path was difficult, but Leo ___ (MANAGE) reach the top. [2 words]","answer":"managed to","why":"Конкретное достижение: managed to.","options":null},{"id":"v35-g5t2-2-4","prompt":"From next month, Maya ___ (BE ABLE TO) work remotely. [future, 4 words]","answer":"will be able to","why":"Запланированная возможность.","options":null},{"id":"v35-g5t2-2-5","prompt":"Last night I ___ (NOT BE ABLE TO) connect to the server.","answer":"was not able to||wasn't able to","why":"Отрицание прошлой возможности: wasn't able to.","options":null},{"id":"v35-g5t2-2-6","prompt":"My grandparents ___ (BE ABLE TO) use the app since we showed them how. [4 words]","answer":"have been able to","why":"Since + период до настоящего: have been able to.","options":null},{"id":"v35-g5t2-2-7","prompt":"___ (BE) you able to hear the announcement yesterday?","answer":"Were","why":"Вопрос о прошлом с you: Were.","options":null},{"id":"v35-g5t2-2-8","prompt":"You must ___ (BE ABLE TO) show your ticket. [3 words]","answer":"be able to","why":"После must используем be able to.","options":null},{"id":"v35-g5t2-2-9","prompt":"We ___ (BE ABLE TO) play outside today: the weather is fine. [present, 2 words]","answer":"are able to","why":"Настоящая возможность с we: are able to.","options":null},{"id":"v35-g5t2-2-10","prompt":"My sister ___ (BE ABLE TO) solve the problem when everybody else failed. [3 words]","answer":"was able to","why":"Конкретный результат в прошлом.","options":null},{"id":"v35-g5t2-2-11","prompt":"I hope I ___ (BE ABLE TO) pass the exam next year. [4 words]","answer":"will be able to","why":"Надежда о будущем: will be able to.","options":null},{"id":"v35-g5t2-2-12","prompt":"They ___ (NOT BE ABLE TO) reach the island because of the fog yesterday. [4 words]","answer":"were not able to||weren't able to","why":"Вчера: weren't able to.","options":null}]]},"Must и have to":{"slug":"g5t3","theory":"<article class=\"gm35 gm35-topic-3\" id=\"rule-theory\" lang=\"ru\"><header><small>МОДАЛЬНОСТЬ · ИСТОЧНИК ОБЯЗАННОСТИ</small><h2>Must и have to: почему действие необходимо?</h2><p>Оба варианта могут переводиться как «должен». Разницу легче увидеть, если спросить: <b>кто или что создаёт необходимость?</b> Но в реальном употреблении формы часто взаимозаменяемы, особенно в утвердительных предложениях.</p></header>\n<section><h3>Откуда берётся обязанность?</h3><div class=\"gm35-grid two\"><article><b>Must: позиция говорящего, настойчивая инструкция</b><p>You <b>must</b> see this film. — Ты обязательно должен посмотреть этот фильм (совет говорящего).</p></article><article><b>Have to: обстоятельства, внешние требования</b><p>I <b>have to</b> wear a uniform at school. — Я должен носить форму по школьным правилам.</p></article></div><p>В правилах и инструкциях тоже встречается <b>must</b>: Visitors must show ID. — Посетители обязаны предъявить удостоверение. Не пытайся механически переводить любую «внешнюю» обязанность только через have to.</p></section>\n<section><h3>Сравни формы по временам</h3><div class=\"gm35-table\"><table><tr><th>Когда?</th><th>Must</th><th>Have to</th></tr><tr><td>Сейчас</td><td>I <b>must</b> leave.</td><td>I <b>have to</b> leave.</td></tr><tr><td>Вчера</td><td>—</td><td>I <b>had to</b> leave.</td></tr><tr><td>Завтра</td><td>—</td><td>I <b>will have to</b> leave.</td></tr><tr><td>Вопрос</td><td>Must I go?</td><td><b>Do</b> I <b>have to</b> go?</td></tr></table></div><p>После must — V1 без to: We must <b>study</b>. После have to — V1: We have to <b>study</b>. В третьем лице: She <b>has to</b> study. Прошедшее <b>had to</b> описывает необходимость, а не уверенный вывод о прошлом.</p></section>\n<section><h3>Другой must: логический вывод</h3><p>She has studied all night. She <b>must be</b> tired. — Она, должно быть, устала. Здесь нет обязанности: говорящий делает <b>уверенный вывод</b> по признакам. Ср.: She has to be at school at eight (расписание/обязанность).</p><div class=\"gm35-error\"><s>Yesterday I must wear a uniform.</s><b>Yesterday I had to wear a uniform.</b><small>О прошлой обязанности говорим had to.</small></div><div class=\"gm35-error\"><s>Does he must study?</s><b>Must he study? / Does he have to study?</b><small>Must не требует does.</small></div></section></article>","levels":[[{"id":"v35-g5t3-0-1","prompt":"You ___ wear a helmet here. It's a safety rule. (use HAVE TO)","answer":"have to","why":"Внешнее правило: have to.","options":["have to","must","has","have"]},{"id":"v35-g5t3-0-2","prompt":"My brother ___ to leave at seven every morning.","answer":"has","why":"3-е лицо has to.","options":["have","had","will","has"]},{"id":"v35-g5t3-0-3","prompt":"I ___ finish this now. It's really important to me. (use MUST)","answer":"must","why":"Настойчивая необходимость с позиции говорящего.","options":["will","Do","must","had"]},{"id":"v35-g5t3-0-4","prompt":"We ___ to take a different road yesterday.","answer":"had","why":"Прошедшее обязательство: had to.","options":["Did","had","will","Do"]},{"id":"v35-g5t3-0-5","prompt":"___ you have to wear a uniform at school?","answer":"Do","why":"Вопрос с have to + do.","options":["Do","will","Did","must"]},{"id":"v35-g5t3-0-6","prompt":"We ___ have to pay an extra fee next year. (future)","answer":"will","why":"Будущее обязательство: will have to.","options":["Did","must","has","will"]},{"id":"v35-g5t3-0-7","prompt":"She ___ be exhausted after that marathon. (strong deduction)","answer":"must","why":"Логический вывод, не приказ.","options":["have","had","must","has"]},{"id":"v35-g5t3-0-8","prompt":"My mum ___ to work on Saturdays. (routine obligation)","answer":"has","why":"She has to.","options":["will","has","have","had"]},{"id":"v35-g5t3-0-9","prompt":"You ___ read the instructions before using the machine. (firm instruction)","answer":"must","why":"Must подходит для строгой инструкции.","options":["must","had","will","Do"]},{"id":"v35-g5t3-0-10","prompt":"I ___ to get a visa for my last trip.","answer":"had","why":"Past obligation: had to.","options":["will","Do","Did","had"]},{"id":"v35-g5t3-0-11","prompt":"___ we have to book seats in advance?","answer":"Do","why":"Форма вопроса: Do we have to...?","options":["Did","must","Do","will"]},{"id":"v35-g5t3-0-12","prompt":"The train is delayed; I ___ to call my family.","answer":"have","why":"Возникающая необходимость: have to.","options":["has","have","Did","must"]}],[{"id":"v35-g5t3-1-1","prompt":"Correct: Does he must go now?","answer":"Must he go now?||Does he have to go now?","why":"Must не требует does.","options":null},{"id":"v35-g5t3-1-2","prompt":"Change to past: I have to study today.","answer":"I had to study yesterday.","why":"У have to прошедшая форма had to, заменили указатель времени.","options":null},{"id":"v35-g5t3-1-3","prompt":"Correct: She have to practise every day.","answer":"She has to practise every day.","why":"She has to.","options":null},{"id":"v35-g5t3-1-4","prompt":"Make negative: They have to leave now.","answer":"They don't have to leave now.||They do not have to leave now.","why":"Обычное отрицание have to с don't.","options":null},{"id":"v35-g5t3-1-5","prompt":"Make a question: He has to wear glasses.","answer":"Does he have to wear glasses?","why":"Does + he + have to.","options":null},{"id":"v35-g5t3-1-6","prompt":"Correct: You must to finish.","answer":"You must finish.","why":"После must — V1 без to.","options":null},{"id":"v35-g5t3-1-7","prompt":"Use WILL HAVE TO: We have to change plans tomorrow.","answer":"We will have to change plans tomorrow.","why":"Будущая необходимость: will have to.","options":null},{"id":"v35-g5t3-1-8","prompt":"Correct: Yesterday I must take a taxi.","answer":"Yesterday I had to take a taxi.","why":"Обязанность в прошлом: had to.","options":null},{"id":"v35-g5t3-1-9","prompt":"Make a question: They had to wait outside.","answer":"Did they have to wait outside?","why":"Вопрос в Past Simple: Did + have to.","options":null},{"id":"v35-g5t3-1-10","prompt":"Correct: The children has to be quiet.","answer":"The children have to be quiet.","why":"Children во множественном числе.","options":null},{"id":"v35-g5t3-1-11","prompt":"Use MUST for advice: It's really important that you call her.","answer":"You must call her.","why":"Настойчивый совет говорящего.","options":null},{"id":"v35-g5t3-1-12","prompt":"Write a deduction using MUST: Her lights are on, so I believe she is at home.","answer":"She must be at home.","why":"Must be = сильное предположение.","options":null}],[{"id":"v35-g5t3-2-1","prompt":"Because of the storm, we ___ (HAVE TO) stay inside yesterday.","answer":"had to","why":"В прошедшем внешнем обстоятельстве: had to.","options":null},{"id":"v35-g5t3-2-2","prompt":"At our school, each student ___ (HAVE TO) bring an ID card.","answer":"has to","why":"Each student = he/she, has to.","options":null},{"id":"v35-g5t3-2-3","prompt":"You ___ (MUST) not share your password. [write MUST]","answer":"must","why":"Строгая инструкция: must.","options":null},{"id":"v35-g5t3-2-4","prompt":"They ___ (HAVE TO) submit the project next Friday. [future, 3 words]","answer":"will have to","why":"Будущая обязанность.","options":null},{"id":"v35-g5t3-2-5","prompt":"My brother ___ (HAVE TO) help at home every weekend. [present, 2 words]","answer":"has to","why":"Регулярная обязанность: has to.","options":null},{"id":"v35-g5t3-2-6","prompt":"___ (DO) the volunteers have to arrive before nine?","answer":"Do","why":"Present Simple question with volunteers.","options":null},{"id":"v35-g5t3-2-7","prompt":"I ___ (HAVE TO) catch the early bus last Monday.","answer":"had to","why":"Last Monday: had to.","options":null},{"id":"v35-g5t3-2-8","prompt":"The coach says we ___ (MUST) train regularly to improve.","answer":"must","why":"Совет/инструкция от тренера.","options":null},{"id":"v35-g5t3-2-9","prompt":"The shop is closed; we ___ (HAVE TO) come back tomorrow. [2 words]","answer":"have to","why":"Обстоятельства вынуждают вернуться.","options":null},{"id":"v35-g5t3-2-10","prompt":"He ___ (MUST) be hungry after six hours without food.","answer":"must","why":"Логический вывод о состоянии.","options":null},{"id":"v35-g5t3-2-11","prompt":"___ (DID) you have to change trains in Moscow?","answer":"Did","why":"Прошедший вопрос: Did ... have to.","options":null},{"id":"v35-g5t3-2-12","prompt":"This online course ___ (HAVE TO) be completed by April next year. [future, 3 words]","answer":"will have to","why":"Будущее обязательство: will have to be completed.","options":null}]]},"Mustn’t и don’t have to":{"slug":"g5t4","theory":"<article class=\"gm35 gm35-topic-4\" id=\"rule-theory\" lang=\"ru\"><header><small>МОДАЛЬНОСТЬ · ЗАПРЕТ И НЕОБЯЗАТЕЛЬНОСТЬ</small><h2>Mustn't ≠ don't have to: противоположность меняет смысл</h2><p>Это одна из самых важных пар для экзамена: внешне оба предложения отрицательные, но одно <b>запрещает</b>, другое <b>разрешает не делать</b>.</p></header>\n<section><h3>Представь две таблички</h3><div class=\"gm35-polarity\"><article><strong>STOP · MUSTN'T</strong><p>You <b>mustn't touch</b> this machine. — Эту машину <b>нельзя</b> трогать.</p><small>Действие запрещено</small></article><article><strong>OPTIONAL · DON'T HAVE TO</strong><p>You <b>don't have to come</b> early. — Тебе <b>необязательно</b> приходить рано.</p><small>Можно прийти, но не требуется</small></article></div><p>«Не нужно» в русском двусмысленно. Перед выбором английской формы проверь: <b>нельзя</b> или <b>можно, но необязательно</b>?</p></section>\n<section><h3>Правило и времена</h3><div class=\"gm35-table\"><table><tr><th>Запрет</th><th>Отсутствие обязанности</th></tr><tr><td>You <b>mustn't</b> use your phone here.</td><td>You <b>don't have to</b> bring a laptop.</td></tr><tr><td>We <b>mustn't</b> be late.</td><td>She <b>doesn't have to</b> stay.</td></tr><tr><td><b>Не путай</b> с выводом <i>can't be</i></td><td>Yesterday I <b>didn't have to</b> work.</td></tr></table></div><p><b>Mustn't</b> + V1 без to; <b>don't / doesn't / didn't have to</b> + V1. Сокращение <b>mustn't</b> пишется с апострофом. В прошедшем для запрета в соответствующем контексте часто: <b>weren't allowed to</b> (нам было запрещено).</p></section>\n<section><h3>Смысловой тест</h3><p>В школьной библиотеке: Students <b>mustn't talk</b> loudly. — Шуметь запрещено. На прогулке: Students <b>don't have to wear</b> a uniform. — Форма необязательна. Это не совет и не степень вероятности, а модальность разрешения/обязанности.</p><div class=\"gm35-error\"><s>You mustn't bring food if you don't want to.</s><b>You don't have to bring food if you don't want to.</b><small>Контекст говорит об отсутствии обязанности, не о запрете.</small></div><div class=\"gm35-error\"><s>She don't have to come.</s><b>She doesn't have to come.</b><small>Обычный have to в отрицании требует does с he/she/it.</small></div></section></article>","levels":[[{"id":"v35-g5t4-0-1","prompt":"Passengers ___ smoke on the plane. (prohibition)","answer":"mustn't","why":"Прямой запрет: mustn't.","options":["mustn't","don't","doesn't","didn't"]},{"id":"v35-g5t4-0-2","prompt":"You ___ have to print the ticket: a QR code is enough.","answer":"don't","why":"Необязательность: don't have to.","options":["doesn't","didn't","must","don't"]},{"id":"v35-g5t4-0-3","prompt":"My sister ___ have to attend today; she's ill.","answer":"doesn't","why":"She doesn't have to.","options":["must","can't","doesn't","didn't"]},{"id":"v35-g5t4-0-4","prompt":"You ___ take photos here: it's forbidden.","answer":"mustn't","why":"Запрет.","options":["don't","mustn't","must","can't"]},{"id":"v35-g5t4-0-5","prompt":"We ___ have to hurry: the train leaves in two hours.","answer":"don't","why":"Нет необходимости спешить.","options":["don't","can't","mustn't","doesn't"]},{"id":"v35-g5t4-0-6","prompt":"Visitors ___ feed the animals. (strict rule)","answer":"mustn't","why":"Правило запрещает кормить.","options":["don't","doesn't","didn't","mustn't"]},{"id":"v35-g5t4-0-7","prompt":"He ___ have to study Latin in his school.","answer":"doesn't","why":"Нет обязанности; he doesn't have to.","options":["didn't","must","doesn't","don't"]},{"id":"v35-g5t4-0-8","prompt":"You ___ touch that wire; it's dangerous.","answer":"mustn't","why":"Запрет по безопасности.","options":["can't","mustn't","didn't","must"]},{"id":"v35-g5t4-0-9","prompt":"Yesterday we ___ have to pay for entry: it was free.","answer":"didn't","why":"Не было необходимости платить.","options":["didn't","must","can't","mustn't"]},{"id":"v35-g5t4-0-10","prompt":"Children ___ cross the road on a red light.","answer":"mustn't","why":"Запрещено переходить.","options":["can't","don't","doesn't","mustn't"]},{"id":"v35-g5t4-0-11","prompt":"I ___ have to stay after class; it's optional.","answer":"don't","why":"Необязательное действие.","options":["doesn't","didn't","don't","mustn't"]},{"id":"v35-g5t4-0-12","prompt":"Players ___ use their phones during the match.","answer":"mustn't","why":"Запрет правилами.","options":["must","mustn't","doesn't","didn't"]}],[{"id":"v35-g5t4-1-1","prompt":"Replace with MUSTN'T: It is forbidden to enter this room.","answer":"You mustn't enter this room.","why":"Mustn't + V1 обозначает запрет.","options":null},{"id":"v35-g5t4-1-2","prompt":"Replace with DON'T HAVE TO: There is no need to bring a pen.","answer":"You don't have to bring a pen.","why":"Необязательность, не запрет.","options":null},{"id":"v35-g5t4-1-3","prompt":"Correct: You mustn't bring food if you don't want to. [food is optional]","answer":"You don't have to bring food if you don't want to.","why":"Mustn't означало бы запрет.","options":null},{"id":"v35-g5t4-1-4","prompt":"Correct: She don't have to pay.","answer":"She doesn't have to pay.","why":"3-е лицо: doesn't.","options":null},{"id":"v35-g5t4-1-5","prompt":"Make negative permission rule: You can enter. [make a strict prohibition using MUSTN'T]","answer":"You mustn't enter.","why":"Запрет меняет can на mustn't.","options":null},{"id":"v35-g5t4-1-6","prompt":"Correct: We mustn't to talk here.","answer":"We mustn't talk here.","why":"После mustn't нет to.","options":null},{"id":"v35-g5t4-1-7","prompt":"Rewrite with DIDN'T HAVE TO: It wasn't necessary for us to wait.","answer":"We didn't have to wait.","why":"Прошлая необязательность: didn't have to.","options":null},{"id":"v35-g5t4-1-8","prompt":"Correct: He mustn't has a ticket. [meaning: no ticket required]","answer":"He doesn't have to have a ticket.","why":"Не нужен билет, не запрет на его наличие.","options":null},{"id":"v35-g5t4-1-9","prompt":"Make question: She doesn't have to stay. [ask if necessary]","answer":"Does she have to stay?","why":"Does + have to.","options":null},{"id":"v35-g5t4-1-10","prompt":"Replace with MUSTN'T: Students are not allowed to use calculators.","answer":"Students mustn't use calculators.","why":"Не разрешено: mustn't.","options":null},{"id":"v35-g5t4-1-11","prompt":"Correct: You don't must wear a seat belt. [meaning: no obligation]","answer":"You don't have to wear a seat belt.","why":"С have to отрицание через don't; условие специально об отсутствии обязанности.","options":null},{"id":"v35-g5t4-1-12","prompt":"Rewrite with DOESN'T HAVE TO: For Tom, the meeting is optional.","answer":"Tom doesn't have to attend the meeting.","why":"Optional означает отсутствие обязанности.","options":null}],[{"id":"v35-g5t4-2-1","prompt":"The sign says: NO ENTRY. You ___ (MUST) go beyond this point. [negative]","answer":"mustn't","why":"Запрет.","options":null},{"id":"v35-g5t4-2-2","prompt":"Online tickets are accepted. You ___ (HAVE TO) print anything. [negative, 3 words]","answer":"don't have to","why":"Отсутствие обязанности.","options":null},{"id":"v35-g5t4-2-3","prompt":"The exam rules forbid dictionaries. You ___ (MUST) use a dictionary during the test. [negative]","answer":"mustn't","why":"Словарь запрещён правилами.","options":null},{"id":"v35-g5t4-2-4","prompt":"Our homework is optional today. We ___ (HAVE TO) submit it. [negative, 3 words]","answer":"don't have to","why":"Необязательно отправлять.","options":null},{"id":"v35-g5t4-2-5","prompt":"The lab rules say NO FOOD. Students ___ (MUST) eat there. [negative]","answer":"mustn't","why":"Запрет из правил.","options":null},{"id":"v35-g5t4-2-6","prompt":"Lily has finished her work. She ___ (HAVE TO) stay late. [negative, 3 words]","answer":"doesn't have to","why":"Нет нужды оставаться.","options":null},{"id":"v35-g5t4-2-7","prompt":"We got free museum passes, so we ___ (HAVE TO) buy tickets yesterday. [negative, 3 words]","answer":"didn't have to","why":"Прошлая необязательность.","options":null},{"id":"v35-g5t4-2-8","prompt":"Keep away from the river: you ___ (MUST) swim here. [negative]","answer":"mustn't","why":"Правило безопасности.","options":null},{"id":"v35-g5t4-2-9","prompt":"Parents can pick up children, but they ___ (HAVE TO) come themselves. [negative, 3 words]","answer":"don't have to","why":"Это необязательно.","options":null},{"id":"v35-g5t4-2-10","prompt":"This parking space is reserved. You ___ (MUST) leave your car here. [negative]","answer":"mustn't","why":"Запрет парковки.","options":null},{"id":"v35-g5t4-2-11","prompt":"At this event, children under six ___ (HAVE TO) pay. [negative, 3 words]","answer":"don't have to","why":"Бесплатный вход исключает необходимость оплаты.","options":null},{"id":"v35-g5t4-2-12","prompt":"The coach insists on warming up: You ___ (MUST) skip warm-up exercises. [negative]","answer":"mustn't","why":"Запрещено пропускать разминку.","options":null}]]},"Should и ought to":{"slug":"g5t5","theory":"<article class=\"gm35 gm35-topic-5\" id=\"rule-theory\" lang=\"ru\"><header><small>МОДАЛЬНОСТЬ · СОВЕТ И ОЖИДАНИЕ</small><h2>Should и ought to: совет без приказа</h2><p>Когда мы советуем, мы не устанавливаем закон. <b>Should</b> и <b>ought to</b> выражают рекомендацию, разумный выбор, а иногда и ожидание результата.</p></header>\n<section><h3>Диагностика ситуации</h3><div class=\"gm35-grid two\"><article><b>Совет</b><p>You <b>should get</b> more sleep. — Тебе стоит больше спать.</p><p>You <b>ought to apologise</b>. — Тебе следует извиниться.</p></article><article><b>Ожидание</b><p>The parcel <b>should arrive</b> tomorrow. — Посылка, вероятно, придёт завтра.</p><p>This ought to work. — Это, по идее, должно сработать.</p></article></div><p>В первой ситуации речь об этичном или полезном действии, во второй — о вероятности, основанной на ожиданиях.</p></section>\n<section><h3>Формы</h3><div class=\"gm35-table\"><table><tr><th></th><th>Should</th><th>Ought to</th></tr><tr><td>Утверждение</td><td>You should call.</td><td>You ought to call.</td></tr><tr><td>Отрицание</td><td>You shouldn't call.</td><td>You ought not to call.</td></tr><tr><td>Вопрос</td><td>Should I call?</td><td>Ought I to call? (формальнее/реже)</td></tr></table></div><p>После <b>should</b> — V1 без to, после <b>ought</b> — обязательно <b>to + V1</b>. В современном разговорном английском чаще используют should, особенно в вопросах и отрицаниях.</p></section>\n<section><h3>Чем отличаются от must?</h3><p><b>You must see a doctor</b> — настоятельная необходимость. <b>You should see a doctor</b> — рекомендация. Не делай вывод, что should всегда означает слабую степень обязательности: контекст важнее перевода.</p><div class=\"gm35-error\"><s>She should to practise.</s><b>She should practise.</b><small>To нельзя после should.</small></div><div class=\"gm35-error\"><s>He ought study harder.</s><b>He ought to study harder.</b><small>После ought требуется to.</small></div><p>Контроль ОГЭ: по ситуации определи совет / ожидание / приказ и выбери форму, затем проверь частицу to.</p></section></article>","levels":[[{"id":"v35-g5t5-0-1","prompt":"You look exhausted. You ___ get some rest.","answer":"should","why":"Совет человеку.","options":["should","ought","shouldn't","ought to"]},{"id":"v35-g5t5-0-2","prompt":"You ___ to check the train times before leaving.","answer":"ought","why":"Ought to + V1.","options":["shouldn't","Should","ought to","ought"]},{"id":"v35-g5t5-0-3","prompt":"He ___ not eat so much sugar. (use SHOULD)","answer":"should","why":"Should not — мягкий совет.","options":["could","ought","should","ought to"]},{"id":"v35-g5t5-0-4","prompt":"The bus left ten minutes ago. It ___ arrive soon.","answer":"should","why":"Ожидание по расписанию.","options":["shouldn't","should","could","ought"]},{"id":"v35-g5t5-0-5","prompt":"I think we ___ apologise for being late.","answer":"should","why":"Совет о правильном поступке.","options":["should","ought","shouldn't","ought to"]},{"id":"v35-g5t5-0-6","prompt":"Children ___ to respect other people.","answer":"ought","why":"Нормативный совет: ought to.","options":["should","shouldn't","Should","ought"]},{"id":"v35-g5t5-0-7","prompt":"___ I tell the teacher about the mistake?","answer":"Should","why":"Вопрос о совете: Should I...?","options":["could","ought","Should","ought to"]},{"id":"v35-g5t5-0-8","prompt":"This medicine ___ help with the symptoms. (expectation)","answer":"should","why":"Ожидаемый эффект.","options":["shouldn't","should","could","ought"]},{"id":"v35-g5t5-0-9","prompt":"They ___ to take a map; the signal is weak.","answer":"ought","why":"Совет: ought to take.","options":["ought","ought to","could","should"]},{"id":"v35-g5t5-0-10","prompt":"You ___ put off the work until midnight. [negative SHOULD]","answer":"shouldn't","why":"Отрицательная рекомендация.","options":["could","should","ought","shouldn't"]},{"id":"v35-g5t5-0-11","prompt":"We ___ start preparing early.","answer":"should","why":"Совет о подготовке.","options":["could","ought","should","ought to"]},{"id":"v35-g5t5-0-12","prompt":"The new update ___ solve the problem. (reasonable expectation)","answer":"should","why":"Ожидание результата.","options":["shouldn't","should","could","ought"]}],[{"id":"v35-g5t5-1-1","prompt":"Correct: She should to study.","answer":"She should study.","why":"Без to после should.","options":null},{"id":"v35-g5t5-1-2","prompt":"Correct: They ought read the instructions.","answer":"They ought to read the instructions.","why":"Ought to, не ought + V1.","options":null},{"id":"v35-g5t5-1-3","prompt":"Make negative: You should leave immediately.","answer":"You shouldn't leave immediately.||You should not leave immediately.","why":"Should not выражает совет не делать.","options":null},{"id":"v35-g5t5-1-4","prompt":"Make question: I should ask her.","answer":"Should I ask her?","why":"Вопрос с should перед I.","options":null},{"id":"v35-g5t5-1-5","prompt":"Use OUGHT TO: You should say sorry.","answer":"You ought to say sorry.","why":"Советы близки по смыслу.","options":null},{"id":"v35-g5t5-1-6","prompt":"Correct: He doesn't should worry.","answer":"He shouldn't worry.||He should not worry.","why":"Отрицание should без doesn't.","options":null},{"id":"v35-g5t5-1-7","prompt":"Use SHOULD: It would be sensible for you to wait.","answer":"You should wait.","why":"Should передаёт рекомендацию.","options":null},{"id":"v35-g5t5-1-8","prompt":"Correct: You ought not study tonight.","answer":"You ought not to study tonight.","why":"В отрицании ought not to.","options":null},{"id":"v35-g5t5-1-9","prompt":"Make a question: She should tell the truth.","answer":"Should she tell the truth?","why":"Вынеси should перед she.","options":null},{"id":"v35-g5t5-1-10","prompt":"Correct: We should to invite Alex.","answer":"We should invite Alex.","why":"Should + V1.","options":null},{"id":"v35-g5t5-1-11","prompt":"Use OUGHT TO: It would be wise for them to save money.","answer":"They ought to save money.","why":"Ought to = совет.","options":null},{"id":"v35-g5t5-1-12","prompt":"Make negative: He ought to drive so fast.","answer":"He ought not to drive so fast.","why":"Отрицательное ought not to.","options":null}],[{"id":"v35-g5t5-2-1","prompt":"The weather forecast says the snow ___ (SHOULD) stop by noon.","answer":"should","why":"Ожидаемое событие, не обязанность.","options":null},{"id":"v35-g5t5-2-2","prompt":"Before a long journey, drivers ___ (OUGHT) check their tyres. [2 words]","answer":"ought to","why":"Рекомендация: ought to.","options":null},{"id":"v35-g5t5-2-3","prompt":"I have an exam tomorrow. I ___ (SHOULD) go to bed earlier.","answer":"should","why":"Разумный совет себе.","options":null},{"id":"v35-g5t5-2-4","prompt":"Lena is worried. Her friends ___ (SHOULD) listen to her.","answer":"should","why":"Рекомендация.","options":null},{"id":"v35-g5t5-2-5","prompt":"The train is usually on time; it ___ (SHOULD) be here at six.","answer":"should","why":"Ожидаемое время прибытия.","options":null},{"id":"v35-g5t5-2-6","prompt":"People ___ (OUGHT) be polite to the staff. [2 words]","answer":"ought to","why":"Моральный совет.","options":null},{"id":"v35-g5t5-2-7","prompt":"We ___ (SHOULD NOT) ignore these safety instructions. [сокращение допускается]","answer":"shouldn't||should not","why":"Советуем не игнорировать правила.","options":null},{"id":"v35-g5t5-2-8","prompt":"The instructions are unclear. You ___ (SHOULD) ask for help.","answer":"should","why":"Совет.","options":null},{"id":"v35-g5t5-2-9","prompt":"You ___ (OUGHT) spend all your savings at once. [negative, 3 words]","answer":"ought not to","why":"Отрицательная рекомендация.","options":null},{"id":"v35-g5t5-2-10","prompt":"He ___ (SHOULD) feel better after a few days of rest.","answer":"should","why":"Разумное ожидание.","options":null},{"id":"v35-g5t5-2-11","prompt":"As a good friend, I think you ___ (SHOULD) speak honestly.","answer":"should","why":"Рекомендация говорящего.","options":null},{"id":"v35-g5t5-2-12","prompt":"We ___ (OUGHT) arrive early to avoid queues. [2 words]","answer":"ought to","why":"Совет: ought to.","options":null}]]},"May и might":{"slug":"g5t6","theory":"<article class=\"gm35 gm35-topic-6\" id=\"rule-theory\" lang=\"ru\"><header><small>МОДАЛЬНОСТЬ · НЕУВЕРЕННОСТЬ И РАЗРЕШЕНИЕ</small><h2>May и might: мы не знаем наверняка</h2><p>Оба глагола выражают <b>возможность</b>. Не существует надёжного правила «may = 70%, might = 30%»: различие часто определяется стилем, оттенком сомнения и контекстом.</p></header>\n<section><h3>Шкала отношения говорящего</h3><div class=\"gm35-flow\"><span><b>must be</b><small>уверенный вывод</small></span><span><b>may / might be</b><small>возможный вариант</small></span><span><b>can't be</b><small>почти исключено</small></span></div><p>She <b>may be</b> at home. — Возможно, она дома. She <b>might be</b> at home. — Возможно, она дома (нередко звучит осторожнее). Ни одна форма сама по себе не сообщает точную вероятность.</p></section>\n<section><h3>Не путай настоящее, будущее и прошлое</h3><div class=\"gm35-table\"><table><tr><th>Значение</th><th>Пример</th></tr><tr><td>Возможность сейчас</td><td>He <b>might know</b> the answer. — Возможно, он знает ответ.</td></tr><tr><td>Возможность позже</td><td>It <b>may rain</b> tonight. — Может пойти дождь.</td></tr><tr><td>Предположение о прошлом</td><td>She <b>might have missed</b> the bus. — Возможно, она опоздала на автобус.</td></tr></table></div><p><b>May/might + V1</b> без to; для догадки о прошлом: <b>may/might have + V3</b>. Не путай с <b>might have to</b> — «возможно, придётся».</p></section>\n<section><h3>May I...? — разрешение</h3><p><b>May I come in?</b> — Можно войти? Это вежливый, сравнительно формальный запрос разрешения. В повседневной речи часто <b>Can I ...?</b> / <b>Could I ...?</b>. Отрицательное <b>may not</b> в значении возможности — «возможно, не» (We may not go), а запрет в правилах — другое значение (Visitors may not enter).</p><div class=\"gm35-error\"><s>She might to be late.</s><b>She might be late.</b><small>После might нет to.</small></div><div class=\"gm35-error\"><s>He may is at school.</s><b>He may be at school.</b><small>После may используют начальную форму be.</small></div></section></article>","levels":[[{"id":"v35-g5t6-0-1","prompt":"It ___ rain later; the clouds look dark. (uncertain possibility; use MAY)","answer":"may","why":"May rain выражает возможность.","options":["may","might","must","can"]},{"id":"v35-g5t6-0-2","prompt":"She ___ be at the library, but I'm not sure. (use MIGHT)","answer":"might","why":"Осторожное предположение.","options":["May","must","can","might"]},{"id":"v35-g5t6-0-3","prompt":"___ I ask you a question? (formal permission)","answer":"May","why":"May I...? — вежливое разрешение.","options":["could","might","May","can"]},{"id":"v35-g5t6-0-4","prompt":"They ___ come tomorrow; they haven't decided. (use MIGHT)","answer":"might","why":"Неопределённое будущее.","options":["may","might","can","could"]},{"id":"v35-g5t6-0-5","prompt":"The answer ___ be correct; we need to check it. (use MAY)","answer":"may","why":"Неуверенный вывод.","options":["may","might","must","can"]},{"id":"v35-g5t6-0-6","prompt":"He ___ not know the new address. (use MAY)","answer":"may","why":"May not = возможно, не знает.","options":["must","can","could","may"]},{"id":"v35-g5t6-0-7","prompt":"You ___ see some rare birds in the park. (use MIGHT)","answer":"might","why":"Ситуационная возможность.","options":["must","can","might","May"]},{"id":"v35-g5t6-0-8","prompt":"___ I sit here? (formal permission)","answer":"May","why":"Разрешение.","options":["must","May","could","might"]},{"id":"v35-g5t6-0-9","prompt":"This message ___ be from my teacher. (use MIGHT)","answer":"might","why":"Вероятностное суждение.","options":["might","can","could","may"]},{"id":"v35-g5t6-0-10","prompt":"The road ___ be closed tomorrow. (possibility; use MAY)","answer":"may","why":"Неуверенная возможность.","options":["must","can","could","may"]},{"id":"v35-g5t6-0-11","prompt":"They ___ have missed the bus. (guess about past; use MIGHT)","answer":"might","why":"Might have + V3.","options":["May","must","might","may"]},{"id":"v35-g5t6-0-12","prompt":"It ___ not be easy, but let's try. (use MAY)","answer":"may","why":"Возможное затруднение.","options":["must","may","could","might"]}],[{"id":"v35-g5t6-1-1","prompt":"Correct: She may to arrive soon.","answer":"She may arrive soon.","why":"May + V1 без to.","options":null},{"id":"v35-g5t6-1-2","prompt":"Correct: He might is late.","answer":"He might be late.","why":"После might используется be.","options":null},{"id":"v35-g5t6-1-3","prompt":"Use MIGHT: Maybe they are at home.","answer":"They might be at home.","why":"Возможность без уверенности.","options":null},{"id":"v35-g5t6-1-4","prompt":"Use MAY: Perhaps it will snow tomorrow.","answer":"It may snow tomorrow.","why":"May + V1 о будущем.","options":null},{"id":"v35-g5t6-1-5","prompt":"Correct: She may has forgotten.","answer":"She may have forgotten.","why":"Догадка о прошлом: may have + V3.","options":null},{"id":"v35-g5t6-1-6","prompt":"Make negative: They might attend the meeting.","answer":"They might not attend the meeting.","why":"Might not без don't.","options":null},{"id":"v35-g5t6-1-7","prompt":"Change to a past guess: He might lose his keys.","answer":"He might have lost his keys.","why":"Для догадки о прошлом: might have lost.","options":null},{"id":"v35-g5t6-1-8","prompt":"Correct: Do they may leave early?","answer":"May they leave early?","why":"May не требует do.","options":null},{"id":"v35-g5t6-1-9","prompt":"Use MAY: It is possible that she doesn't know.","answer":"She may not know.","why":"May not означает возможность отрицательного события.","options":null},{"id":"v35-g5t6-1-10","prompt":"Correct: He might to come later.","answer":"He might come later.","why":"Без to после might.","options":null},{"id":"v35-g5t6-1-11","prompt":"Make a question for permission: I sit here. [use MAY]","answer":"May I sit here?","why":"May I спрашивает разрешение.","options":null},{"id":"v35-g5t6-1-12","prompt":"Use MIGHT HAVE: Perhaps they forgot our address.","answer":"They might have forgotten our address.","why":"Предположение о прошлом.","options":null}],[{"id":"v35-g5t6-2-1","prompt":"No one answers the door. They ___ (MIGHT) be out.","answer":"might","why":"Предположение на основе ситуации.","options":null},{"id":"v35-g5t6-2-2","prompt":"The streets are wet. It ___ (MAY) have rained overnight. [one word]","answer":"may","why":"May have + V3.","options":null},{"id":"v35-g5t6-2-3","prompt":"The flight ___ (MIGHT) be delayed because of fog.","answer":"might","why":"Возможное событие.","options":null},{"id":"v35-g5t6-2-4","prompt":"We ___ (MAY) travel to Kazan next weekend.","answer":"may","why":"Решение ещё не принято.","options":null},{"id":"v35-g5t6-2-5","prompt":"___ (MAY) I borrow this reference book, please?","answer":"May","why":"Вежливый запрос разрешения.","options":null},{"id":"v35-g5t6-2-6","prompt":"He ___ (MIGHT) have left his phone on the train. [one word]","answer":"might","why":"Догадка о прошлом.","options":null},{"id":"v35-g5t6-2-7","prompt":"She ___ (MAY) not understand the instructions.","answer":"may","why":"Возможность отрицательного состояния.","options":null},{"id":"v35-g5t6-2-8","prompt":"The missing document ___ (MIGHT) still be on my desk.","answer":"might","why":"Предположение.","options":null},{"id":"v35-g5t6-2-9","prompt":"Mira ___ (MAY) have misunderstood the question. [one word]","answer":"may","why":"May have + V3.","options":null},{"id":"v35-g5t6-2-10","prompt":"A visitor ___ (MIGHT) ask for directions.","answer":"might","why":"Возможная ситуация.","options":null},{"id":"v35-g5t6-2-11","prompt":"It ___ (MAY) take longer than expected.","answer":"may","why":"Неуверенная оценка длительности.","options":null},{"id":"v35-g5t6-2-12","prompt":"The interview ___ (MIGHT) have ended already. [one word]","answer":"might","why":"Предположение о завершённом событии.","options":null}]]},"Need и needn’t":{"slug":"g5t7","theory":"<article class=\"gm35 gm35-topic-7\" id=\"rule-theory\" lang=\"ru\"><header><small>МОДАЛЬНОСТЬ · НЕОБХОДИМОСТЬ</small><h2>Need / needn't: что требуется, а без чего можно обойтись?</h2><p>В английском <b>need</b> ведёт себя и как обычный глагол, и как модальный (особенно в отрицании). Это объясняет разные формы вопросов и отрицаний.</p></header>\n<section><h3>Два способа сказать «нужно»</h3><div class=\"gm35-grid two\"><article><b>Обычный глагол need</b><p>She <b>needs to buy</b> a ticket. — Ей нужно купить билет.</p><p>Do you <b>need to</b> leave? — Тебе нужно уходить?</p></article><article><b>Модальное needn't</b><p>You <b>needn't hurry</b>. — Можешь не торопиться.</p><p>Need I say more? — Нужно ли мне продолжать? (формальнее)</p></article></div><p><b>Need to + V1</b> образует отрицание и вопросы с <b>do/does/did</b>. Модальное <b>needn't + V1</b> не требует to и do.</p></section>\n<section><h3>Три разные истории</h3><div class=\"gm35-table\"><table><tr><th>Что произошло?</th><th>Фраза</th></tr><tr><td>Необязательно сейчас</td><td>You <b>needn't bring</b> food. — Еду приносить необязательно.</td></tr><tr><td>Не было необходимости вчера</td><td>We <b>didn't need to buy</b> tickets. — Нам не нужно было покупать билеты (покупка не утверждается).</td></tr><tr><td>Зря сделали</td><td>We <b>needn't have bought</b> tickets. — Мы зря купили билеты (покупка была).</td></tr></table></div><p>Важнейшее различие: <b>needn't have + V3</b> подразумевает, что действие <b>произошло</b>, но было ненужным. <b>Didn't need to</b> не доказывает, произошло ли действие.</p></section>\n<section><h3>Проверяй форму</h3><div class=\"gm35-error\"><s>She doesn't need hurry.</s><b>She doesn't need to hurry.</b><small>С обычным need требуется to.</small></div><div class=\"gm35-error\"><s>You needn't to pay.</s><b>You needn't pay.</b><small>Модальное needn't идёт без to.</small></div><p>В экзамене сначала выясни <b>значение</b> (необходимость / необязательность / ненужное выполненное действие), а затем <b>грамматический тип</b> глагола.</p></section></article>","levels":[[{"id":"v35-g5t7-0-1","prompt":"You ___ to complete the form first. (ordinary NEED)","answer":"need","why":"Need to + V1.","options":["need","needs","needn't","doesn't"]},{"id":"v35-g5t7-0-2","prompt":"She ___ to practise every day.","answer":"needs","why":"She needs to.","options":["needn't","doesn't","didn't","needs"]},{"id":"v35-g5t7-0-3","prompt":"We ___ hurry: we've got an hour. (modal negative)","answer":"needn't","why":"Необязательно: needn't + V1.","options":["didn't","Does","needn't","doesn't"]},{"id":"v35-g5t7-0-4","prompt":"___ you need to book in advance?","answer":"Do","why":"Вопрос с ordinary need.","options":["Does","Do","doesn't","didn't"]},{"id":"v35-g5t7-0-5","prompt":"You ___ not need to pay. (write DO)","answer":"do","why":"Отрицание do not need to.","options":["do","didn't","Does","need"]},{"id":"v35-g5t7-0-6","prompt":"He ___ need to come; attendance is optional.","answer":"doesn't","why":"He doesn't need to.","options":["Do","need","needs","doesn't"]},{"id":"v35-g5t7-0-7","prompt":"You ___ have bought a ticket: entry is free! (unnecessary completed action)","answer":"needn't","why":"Needn't have + V3 = сделали зря.","options":["needs","doesn't","needn't","need"]},{"id":"v35-g5t7-0-8","prompt":"They ___ to see a doctor if symptoms persist.","answer":"need","why":"They need to.","options":["didn't","need","needn't","doesn't"]},{"id":"v35-g5t7-0-9","prompt":"I ___ need to go yesterday; the meeting was cancelled.","answer":"didn't","why":"Прошлая необязательность.","options":["didn't","needn't","doesn't","Does"]},{"id":"v35-g5t7-0-10","prompt":"The children ___ to be careful near the river.","answer":"need","why":"Children = they need to.","options":["didn't","Does","Do","need"]},{"id":"v35-g5t7-0-11","prompt":"You ___ worry; the file is safely backed up. (modal negative)","answer":"needn't","why":"Needn't + V1.","options":["Do","need","needn't","Does"]},{"id":"v35-g5t7-0-12","prompt":"___ she need to take the test again?","answer":"Does","why":"Does she need to ...?","options":["needs","Does","Do","need"]}],[{"id":"v35-g5t7-1-1","prompt":"Correct: You needn't to wait.","answer":"You needn't wait.","why":"Модальный needn't идёт без to.","options":null},{"id":"v35-g5t7-1-2","prompt":"Correct: She don't need to go.","answer":"She doesn't need to go.","why":"3-е лицо: doesn't.","options":null},{"id":"v35-g5t7-1-3","prompt":"Rewrite with NEEDN'T: It isn't necessary for you to bring water.","answer":"You needn't bring water.","why":"Модальное отрицание.","options":null},{"id":"v35-g5t7-1-4","prompt":"Make question: He needs to leave now.","answer":"Does he need to leave now?","why":"Does + he + need to.","options":null},{"id":"v35-g5t7-1-5","prompt":"Correct: She need to study harder.","answer":"She needs to study harder.","why":"Обычный need в 3-м лице.","options":null},{"id":"v35-g5t7-1-6","prompt":"Use DIDN'T NEED TO: It wasn't necessary for us to buy tickets.","answer":"We didn't need to buy tickets.","why":"Необходимости не было; не утверждаем, купили ли.","options":null},{"id":"v35-g5t7-1-7","prompt":"Use NEEDN'T HAVE: We bought food, but nobody ate it.","answer":"We needn't have bought food.","why":"Купили зря, действие было совершено.","options":null},{"id":"v35-g5t7-1-8","prompt":"Correct: He needn't to call.","answer":"He needn't call.","why":"Needn't + V1.","options":null},{"id":"v35-g5t7-1-9","prompt":"Make negative: They need to work tonight.","answer":"They don't need to work tonight.||They do not need to work tonight.","why":"Отрицание ordinary need.","options":null},{"id":"v35-g5t7-1-10","prompt":"Make a question: You need to attend.","answer":"Do you need to attend?","why":"Вопрос с do.","options":null},{"id":"v35-g5t7-1-11","prompt":"Correct: Does she needs to pay?","answer":"Does she need to pay?","why":"После does основная форма need.","options":null},{"id":"v35-g5t7-1-12","prompt":"Rewrite with NEEDN'T: You don't have to finish today.","answer":"You needn't finish today.","why":"Отсутствие обязанности.","options":null}],[{"id":"v35-g5t7-2-1","prompt":"The form is optional. You ___ (NEED) complete it. [modal negative, one word]","answer":"needn't","why":"Можно не заполнять.","options":null},{"id":"v35-g5t7-2-2","prompt":"Lena ___ (NEED) to buy a new calculator. [present]","answer":"needs","why":"Need как обычный глагол.","options":null},{"id":"v35-g5t7-2-3","prompt":"We booked the seats, but entrance was free: we ___ (NEED) have booked. [modal negative]","answer":"needn't","why":"Needn't have booked = сделали зря.","options":null},{"id":"v35-g5t7-2-4","prompt":"___ (DO) you need to arrive before nine?","answer":"Do","why":"Вопрос: Do you need to...?","options":null},{"id":"v35-g5t7-2-5","prompt":"At that time, I ___ (NEED) to leave early because of the storm. [past]","answer":"needed","why":"Past Simple ordinary need: needed to.","options":null},{"id":"v35-g5t7-2-6","prompt":"The classroom is warm. You ___ (NEED) wear your coat. [modal negative]","answer":"needn't","why":"Необязательно.","options":null},{"id":"v35-g5t7-2-7","prompt":"The teacher says we ___ (NEED) to revise the vocabulary.","answer":"need","why":"We need to.","options":null},{"id":"v35-g5t7-2-8","prompt":"The school provided laptops, so we ___ (NEED) bring our own. [past negative, 2 words]","answer":"didn't need","why":"Не было необходимости приносить.","options":null},{"id":"v35-g5t7-2-9","prompt":"He ___ (NEED) to take the exam again after failing.","answer":"needs","why":"Требуется повторная попытка.","options":null},{"id":"v35-g5t7-2-10","prompt":"You ___ (NEED) have spent so much money; I had a voucher. [modal negative]","answer":"needn't","why":"Ненужное уже совершённое действие.","options":null},{"id":"v35-g5t7-2-11","prompt":"___ (DO) she need to bring an ID?","answer":"Does","why":"С she используется does.","options":null},{"id":"v35-g5t7-2-12","prompt":"I ___ (NEED) to check the timetable before travelling.","answer":"need","why":"Need to + V1 в настоящем.","options":null}]]},"Запрос разрешения и просьбы":{"slug":"g5t8","theory":"<article class=\"gm35 gm35-topic-8\" id=\"rule-theory\" lang=\"ru\"><header><small>ПРАГМАТИКА · ВЕЖЛИВОСТЬ</small><h2>Разрешение и просьба: одно слово — разные роли</h2><p>Фразы <b>Can I...?</b> и <b>Could you...?</b> внешне похожи, но первая спрашивает о разрешении для <b>себя</b>, а вторая просит <b>другого человека</b> что-то сделать.</p></header>\n<section><h3>Кто выполняет действие?</h3><div class=\"gm35-grid two\"><article><b>Разрешение</b><p><b>May I</b> sit here? — Могу я здесь сесть?</p><p><b>Could I</b> borrow your pen? — Можно мне взять твою ручку?</p></article><article><b>Просьба</b><p><b>Could you</b> send me the file? — Не мог бы ты отправить файл?</p><p><b>Would you mind</b> opening the window? — Не возражаешь открыть окно?</p></article></div><p>С <b>would you mind</b> после mind ставим <b>V-ing</b>. Отрицательный ответ <b>No, not at all</b> означает <i>«совсем не возражаю»</i>, то есть согласие выполнить просьбу.</p></section>\n<section><h3>Выбираем регистр общения</h3><div class=\"gm35-table\"><table><tr><th>Ситуация</th><th>Естественная форма</th></tr><tr><td>Друзья</td><td>Can I use your charger?</td></tr><tr><td>Вежливая просьба учителю</td><td>Could you explain that again, please?</td></tr><tr><td>Более формальное разрешение</td><td>May I leave the room?</td></tr><tr><td>Вежливый вопрос о готовности</td><td>Would you be able to help me?</td></tr></table></div><p>Выбор <b>could</b> вместо <b>can</b> не означает прошедшее время: это способ сделать вопрос менее прямым. Просьбу полезно смягчать <b>please</b>, но оно не заменяет правильной структуры.</p></section>\n<section><h3>Как правильно отвечать</h3><p>Can I open the window? — <b>Yes, of course</b>. / <b>Sorry, not right now</b>. Could you hold the door? — <b>Sure, no problem</b>. / <b>I'm sorry, I can't</b>.</p><div class=\"gm35-error\"><s>Would you mind to wait?</s><b>Would you mind waiting?</b><small>После mind используется V-ing.</small></div><div class=\"gm35-error\"><s>Could you to explain?</s><b>Could you explain?</b><small>После could — инфинитив без to.</small></div><p>На ОГЭ определяй коммуникативную задачу, а не выбирай самую длинную формулу как «самую вежливую».</p></section></article>","levels":[[{"id":"v35-g5t8-0-1","prompt":"___ I come in? (formal permission)","answer":"May","why":"Просим разрешение для себя.","options":["May","Could","Can","Would"]},{"id":"v35-g5t8-0-2","prompt":"___ you pass the salt, please? (polite request)","answer":"Could","why":"Просим другого человека.","options":["Can","Would","waiting","Could"]},{"id":"v35-g5t8-0-3","prompt":"Would you mind ___ the window? (OPEN)","answer":"opening","why":"После mind + V-ing.","options":["Would","waiting","opening","Can"]},{"id":"v35-g5t8-0-4","prompt":"___ I borrow your ruler? (use CAN, informal permission)","answer":"Can","why":"Разрешение.","options":["turn","Can","waiting","opening"]},{"id":"v35-g5t8-0-5","prompt":"___ you help me for a moment? (use WOULD)","answer":"Would","why":"Вежливая просьба с would.","options":["Would","opening","turn","be"]},{"id":"v35-g5t8-0-6","prompt":"___ I leave early, please? (formal)","answer":"May","why":"Формальное разрешение.","options":["turn","be","moving","May"]},{"id":"v35-g5t8-0-7","prompt":"Could you ___ the lights off? (TURN)","answer":"turn","why":"После could — V1.","options":["moving","checking","turn","be"]},{"id":"v35-g5t8-0-8","prompt":"Would you mind ___ a minute? (WAIT)","answer":"waiting","why":"Mind + V-ing.","options":["May","waiting","moving","checking"]},{"id":"v35-g5t8-0-9","prompt":"___ you repeat the last sentence? (use COULD)","answer":"Could","why":"Вежливая просьба.","options":["Could","checking","May","Can"]},{"id":"v35-g5t8-0-10","prompt":"___ I use your notebook for a minute? (use COULD)","answer":"Could","why":"Вежливое разрешение для себя.","options":["May","Can","Would","Could"]},{"id":"v35-g5t8-0-11","prompt":"___ you open the gate? (use CAN)","answer":"Can","why":"Нейтральная просьба.","options":["Would","waiting","Can","Could"]},{"id":"v35-g5t8-0-12","prompt":"Would you ___ able to send the report?","answer":"be","why":"Would you be able to...?","options":["waiting","be","Can","Would"]}],[{"id":"v35-g5t8-1-1","prompt":"Correct: Could you to explain this?","answer":"Could you explain this?","why":"После could не бывает to.","options":null},{"id":"v35-g5t8-1-2","prompt":"Correct: Would you mind to wait?","answer":"Would you mind waiting?","why":"Mind + V-ing.","options":null},{"id":"v35-g5t8-1-3","prompt":"Use MAY I: Is it all right if I enter?","answer":"May I enter?","why":"Формальное разрешение.","options":null},{"id":"v35-g5t8-1-4","prompt":"Use COULD YOU: Please send me the link.","answer":"Could you send me the link, please?","why":"Вежливая просьба.","options":null},{"id":"v35-g5t8-1-5","prompt":"Correct: May you lend me a pen? [request to another person; use COULD]","answer":"Could you lend me a pen?","why":"Нужна просьба об услуге, не разрешение для себя.","options":null},{"id":"v35-g5t8-1-6","prompt":"Use WOULD YOU MIND: Please close the door.","answer":"Would you mind closing the door?","why":"Would you mind + -ing.","options":null},{"id":"v35-g5t8-1-7","prompt":"Correct: Can I to sit here?","answer":"Can I sit here?","why":"После can — V1.","options":null},{"id":"v35-g5t8-1-8","prompt":"Reply YES to permission: May I leave?","answer":"Yes, of course.","why":"Положительный ответ разрешает уход.","options":null},{"id":"v35-g5t8-1-9","prompt":"Reply NO, NOT AT ALL to: Would you mind helping me?","answer":"No, not at all.","why":"Не возражаю = готов помочь.","options":null},{"id":"v35-g5t8-1-10","prompt":"Use COULD I: Please let me borrow your charger.","answer":"Could I borrow your charger?","why":"Запрос разрешения себе.","options":null},{"id":"v35-g5t8-1-11","prompt":"Correct: Would you mind open the window?","answer":"Would you mind opening the window?","why":"После mind форма -ing.","options":null},{"id":"v35-g5t8-1-12","prompt":"Use WOULD YOU: Please check my spelling.","answer":"Would you check my spelling, please?","why":"Вежливая просьба.","options":null}],[{"id":"v35-g5t8-2-1","prompt":"At the library: \"___ (MAY) I take this book home?\"","answer":"May","why":"Запрос разрешения.","options":null},{"id":"v35-g5t8-2-2","prompt":"In a café: \"___ (COULD) you bring the menu, please?\"","answer":"Could","why":"Просим сотрудника выполнить действие.","options":null},{"id":"v35-g5t8-2-3","prompt":"Before the lesson: \"Would you mind ___ (WAIT) outside?\"","answer":"waiting","why":"Mind + V-ing.","options":null},{"id":"v35-g5t8-2-4","prompt":"In a meeting: \"___ (CAN) I ask a question?\"","answer":"Can","why":"Разрешение для себя.","options":null},{"id":"v35-g5t8-2-5","prompt":"At reception: \"___ (COULD) I have a copy of the receipt?\"","answer":"Could","why":"Вежливый запрос.","options":null},{"id":"v35-g5t8-2-6","prompt":"On the train: \"Would you mind ___ (MOVE) your bag?\"","answer":"moving","why":"Mind + V-ing.","options":null},{"id":"v35-g5t8-2-7","prompt":"At school: \"___ (MAY) I speak to the teacher?\"","answer":"May","why":"Формальная просьба разрешить.","options":null},{"id":"v35-g5t8-2-8","prompt":"On the phone: \"___ (COULD) you speak more slowly?\"","answer":"Could","why":"Вежливая просьба.","options":null},{"id":"v35-g5t8-2-9","prompt":"In the lab: \"___ (CAN) I use these goggles?\"","answer":"Can","why":"Вопрос о разрешении.","options":null},{"id":"v35-g5t8-2-10","prompt":"Online class: \"Would you ___ (BE) able to share your screen?\"","answer":"be","why":"Would you be able to...?","options":null},{"id":"v35-g5t8-2-11","prompt":"At a friend's house: \"___ (COULD) I charge my phone here?\"","answer":"Could","why":"Просим разрешение.","options":null},{"id":"v35-g5t8-2-12","prompt":"At the station: \"Would you mind ___ (CHECK) the platform number?\"","answer":"checking","why":"Mind + V-ing.","options":null}]]},"Исчисляемые и неисчисляемые существительные":{"slug":"g6t1","theory":"<article class=\"gm35 gm35-topic-9\" id=\"rule-theory\" lang=\"ru\"><header><small>СУЩЕСТВИТЕЛЬНЫЕ · ТИП СЛОВА</small><h2>Countable / uncountable: что мы считаем?</h2><p>Вопрос не в том, можно ли посчитать вещество в реальности, а в том, как английское слово представляет предмет: как <b>отдельные единицы</b> или как <b>массу, абстрактное понятие</b>.</p></header>\n<section><h3>Тест на исчисляемость</h3><div class=\"gm35-grid two\"><article><b>Можно назвать единицы</b><p><b>an apple → two apples</b><br>яблоко → два яблока</p><p>Есть единственное и множественное число, a/an в единственном числе.</p></article><article><b>Без обычной формы множественного числа</b><p><b>some advice, some information</b><br>совет, информация</p><p>Не говорим <s>an advice</s> / <s>informations</s>.</p></article></div><p>Типичные неисчисляемые для русскоязычных: <b>advice, information, furniture, luggage, homework, news</b>. <b>News</b> оканчивается на -s, но грамматически единственное: <b>The news is</b> surprising.</p></section>\n<section><h3>Как посчитать неисчисляемое?</h3><div class=\"gm35-table\"><table><tr><th>Идея</th><th>Правильно</th></tr><tr><td>Один совет</td><td><b>a piece of advice</b></td></tr><tr><td>Две новости</td><td><b>two pieces of news</b></td></tr><tr><td>Три буханки</td><td><b>three loaves of bread</b></td></tr><tr><td>Два стакана воды</td><td><b>two glasses of water</b></td></tr></table></div><p>Некоторые слова меняют значение: <b>chicken</b> (мясо, неисчисляемое) / <b>a chicken</b> (птица); <b>paper</b> (бумага) / <b>a paper</b> (статья, работа).</p></section>\n<section><h3>Глагол и количество</h3><p><b>Much water is</b> wasted. — Много воды расходуется впустую. <b>Many bottles are</b> wasted. — Много бутылок выбрасывают. Один предмет: <b>an idea</b>, но <b>some information</b> без артикля a.</p><div class=\"gm35-error\"><s>These furnitures are expensive.</s><b>This furniture is expensive.</b><small>Furniture — неисчисляемое: this + is.</small></div><div class=\"gm35-error\"><s>She gave me an advice.</s><b>She gave me a piece of advice.</b><small>Для одной единицы используем piece of.</small></div></section></article>","levels":[[{"id":"v35-g6t1-0-1","prompt":"We need some ___ about the museum. (INFORMATION)","answer":"information","why":"Information — неисчисляемое.","options":["information","advice","apples","furniture"]},{"id":"v35-g6t1-0-2","prompt":"She gave me useful ___. (ADVICE)","answer":"advice","why":"Advice без -s.","options":["apples","furniture","loaves","advice"]},{"id":"v35-g6t1-0-3","prompt":"There are three ___ on the table. (APPLE)","answer":"apples","why":"Исчисляемое во множественном.","options":["loaves","piece","apples","furniture"]},{"id":"v35-g6t1-0-4","prompt":"The ___ is expensive. (FURNITURE)","answer":"furniture","why":"Furniture — неисчисляемое.","options":["news","furniture","loaves","piece"]},{"id":"v35-g6t1-0-5","prompt":"We bought two ___ of bread. (LOAF)","answer":"loaves","why":"Loaf → loaves.","options":["loaves","piece","news","water"]},{"id":"v35-g6t1-0-6","prompt":"Can you give me a ___ of advice? (PIECE)","answer":"piece","why":"Единица неисчисляемого advice.","options":["news","water","article","piece"]},{"id":"v35-g6t1-0-7","prompt":"The ___ is surprising. (NEWS)","answer":"news","why":"News — неисчисляемое по согласованию.","options":["article","homework","news","water"]},{"id":"v35-g6t1-0-8","prompt":"There is not much ___ left. (WATER)","answer":"water","why":"Water как масса.","options":["chicken","water","article","homework"]},{"id":"v35-g6t1-0-9","prompt":"I read an interesting ___ yesterday. (ARTICLE)","answer":"article","why":"Исчисляемое: an article.","options":["article","homework","chicken","chairs"]},{"id":"v35-g6t1-0-10","prompt":"We have a lot of ___ to do. (HOMEWORK)","answer":"homework","why":"Homework без -s.","options":["chicken","chairs","information","homework"]},{"id":"v35-g6t1-0-11","prompt":"This ___ smells good. (CHICKEN, meat)","answer":"chicken","why":"Chicken как мясо — неисчисляемое.","options":["information","advice","chicken","chairs"]},{"id":"v35-g6t1-0-12","prompt":"She bought two ___ for her new flat. (CHAIR)","answer":"chairs","why":"Chairs — отдельные предметы.","options":["apples","chairs","information","advice"]}],[{"id":"v35-g6t1-1-1","prompt":"Correct: She gave me an advice.","answer":"She gave me a piece of advice.","why":"Advice не употребляется с a/an.","options":null},{"id":"v35-g6t1-1-2","prompt":"Correct: These furnitures are heavy.","answer":"This furniture is heavy.","why":"Furniture — неисчисляемое, без мн. числа.","options":null},{"id":"v35-g6t1-1-3","prompt":"Rewrite with TWO: one box","answer":"two boxes","why":"Исчисляемое box → boxes.","options":null},{"id":"v35-g6t1-1-4","prompt":"Correct: I have many homeworks.","answer":"I have a lot of homework.","why":"Homework — неисчисляемое.","options":null},{"id":"v35-g6t1-1-5","prompt":"Rewrite with ONE: two glasses of water","answer":"one glass of water","why":"Glasses → glass, water не меняется.","options":null},{"id":"v35-g6t1-1-6","prompt":"Correct: The news are interesting.","answer":"The news is interesting.","why":"News грамматически единственное число.","options":null},{"id":"v35-g6t1-1-7","prompt":"Rewrite with PIECES: She shared two useful bits of information.","answer":"She shared two useful pieces of information.","why":"Pieces of information измеряет количество.","options":null},{"id":"v35-g6t1-1-8","prompt":"Correct: We bought three breads. [whole loaves]","answer":"We bought three loaves of bread.","why":"Для буханок нужна единица loaf.","options":null},{"id":"v35-g6t1-1-9","prompt":"Correct: Those luggage are mine.","answer":"That luggage is mine.","why":"Luggage — неисчисляемое.","options":null},{"id":"v35-g6t1-1-10","prompt":"Rewrite with TWO: a child","answer":"two children","why":"Неправильное множественное children.","options":null},{"id":"v35-g6t1-1-11","prompt":"Correct: I read two interesting paper. [articles]","answer":"I read two interesting papers.","why":"Paper в значении статьи — исчисляемое.","options":null},{"id":"v35-g6t1-1-12","prompt":"Correct: She wants an information.","answer":"She wants some information.","why":"Information — неисчисляемое.","options":null}],[{"id":"v35-g6t1-2-1","prompt":"Our teacher gave us three ___ (PIECE) of advice.","answer":"pieces","why":"Мера исчисляемая: three pieces.","options":null},{"id":"v35-g6t1-2-2","prompt":"The breaking ___ (NEWS) is on every channel.","answer":"news","why":"News неизменно.","options":null},{"id":"v35-g6t1-2-3","prompt":"A woman entered carrying two ___ (SUITCASE).","answer":"suitcases","why":"Суффикс -s у исчисляемого.","options":null},{"id":"v35-g6t1-2-4","prompt":"We had very little ___ (TIME) before the exam.","answer":"time","why":"Time как длительность неисчисляемо.","options":null},{"id":"v35-g6t1-2-5","prompt":"Several ___ (CHILD) were waiting outside.","answer":"children","why":"Неправильная форма мн. числа.","options":null},{"id":"v35-g6t1-2-6","prompt":"The kitchen needs new ___ (FURNITURE).","answer":"furniture","why":"Нельзя furnitures.","options":null},{"id":"v35-g6t1-2-7","prompt":"Three ___ (LOAF) of bread were on the shelf.","answer":"loaves","why":"Loaf → loaves.","options":null},{"id":"v35-g6t1-2-8","prompt":"The students completed all the ___ (HOMEWORK).","answer":"homework","why":"Homework без -s.","options":null},{"id":"v35-g6t1-2-9","prompt":"She shared important ___ (INFORMATION) with the group.","answer":"information","why":"Information — неисчисляемое.","options":null},{"id":"v35-g6t1-2-10","prompt":"My parents ordered two ___ (CHICKEN) for the farm. [birds]","answer":"chickens","why":"Chicken как птица исчисляемо.","options":null},{"id":"v35-g6t1-2-11","prompt":"We drank two ___ (GLASS) of milk.","answer":"glasses","why":"Контейнеры считаются.","options":null},{"id":"v35-g6t1-2-12","prompt":"One of the ___ (KNIFE) was missing.","answer":"knives","why":"Knife → knives.","options":null}]]},"Much / many / a lot of":{"slug":"g6t2","theory":"<article class=\"gm35 gm35-topic-10\" id=\"rule-theory\" lang=\"ru\"><header><small>СУЩЕСТВИТЕЛЬНЫЕ · КОЛИЧЕСТВО</small><h2>Much, many, a lot of: что именно много?</h2><p>Сначала определи, исчисляемое существительное или нет. Затем учти тип высказывания: <b>many</b> часто употребляется в любом регистре, <b>much</b> особенно типично в вопросах и отрицаниях, а <b>a lot of</b> естественно в утверждениях.</p></header>\n<section><h3>Матрица выбора</h3><div class=\"gm35-table\"><table><tr><th>Что считаем?</th><th>Обычно</th><th>Пример</th></tr><tr><td>Отдельные предметы</td><td><b>many</b> / a lot of</td><td>There are <b>many books</b>. — Много книг.</td></tr><tr><td>Масса, понятие</td><td><b>much</b> / a lot of</td><td>We don't have <b>much time</b>. — Мало времени.</td></tr><tr><td>Нейтральное утверждение</td><td><b>a lot of</b></td><td>She has <b>a lot of friends</b>. — У неё много друзей.</td></tr></table></div><p><b>A lot of</b> сочетается и с исчисляемыми во множественном числе, и с неисчисляемыми. <b>A lot</b> без of может быть наречием: I read a lot. — Я много читаю.</p></section>\n<section><h3>Вопросы и отрицания</h3><div class=\"gm35-grid two\"><article><b>How many + мн. число</b><p>How many <b>questions</b> are there? — Сколько вопросов?</p></article><article><b>How much + неисчисляемое</b><p>How much <b>money</b> do you need? — Сколько денег тебе нужно?</p></article></div><p>Сравни: <b>I don't have much homework</b> / <b>I have a lot of homework</b>. Утвердительное <i>I have much homework</i> грамматически возможно в некоторых формальных контекстах, но в обычном разговоре звучит неестественно.</p></section>\n<section><h3>Согласование и тонкие различия</h3><p>How <b>many students are</b> here? / How <b>much information is</b> here? Глагол согласуется с существительным, а не с much/many.</p><div class=\"gm35-error\"><s>How much apples are there?</s><b>How many apples are there?</b><small>Apples — исчисляемое во множественном числе.</small></div><div class=\"gm35-error\"><s>Many information is available.</s><b>Much information is available. / A lot of information is available.</b><small>Information — неисчисляемое.</small></div></section></article>","levels":[[{"id":"v35-g6t2-0-1","prompt":"How ___ books have you read this month?","answer":"many","why":"Books — исчисляемые.","options":["many","much","lot","How much"]},{"id":"v35-g6t2-0-2","prompt":"How ___ water do we need?","answer":"much","why":"Water — неисчисляемое.","options":["lot","How much","How many","much"]},{"id":"v35-g6t2-0-3","prompt":"There are a ___ of students in the hall.","answer":"lot","why":"A lot of + существительное.","options":["How many","many","lot","How much"]},{"id":"v35-g6t2-0-4","prompt":"I don't have ___ time left. (use MUCH)","answer":"much","why":"Отрицание + неисчисляемое.","options":["lot","much","How many","many"]},{"id":"v35-g6t2-0-5","prompt":"Are there ___ buses after midnight? (ask whether there are many)","answer":"many","why":"Buses можно считать.","options":["many","much","lot","How much"]},{"id":"v35-g6t2-0-6","prompt":"She has a ___ of friends at school.","answer":"lot","why":"Утверждение: a lot of friends.","options":["much","How much","How many","lot"]},{"id":"v35-g6t2-0-7","prompt":"We didn't spend ___ money on the trip. (use MUCH; not much, but some)","answer":"much","why":"Money — неисчисляемое.","options":["How many","many","much","How much"]},{"id":"v35-g6t2-0-8","prompt":"How ___ chairs should we bring?","answer":"many","why":"Chairs — исчисляемые.","options":["lot","many","How many","much"]},{"id":"v35-g6t2-0-9","prompt":"They had ___ visitors last week. (use MANY)","answer":"many","why":"Many visitors.","options":["many","much","lot","How much"]},{"id":"v35-g6t2-0-10","prompt":"I have a ___ of homework tonight.","answer":"lot","why":"A lot of homework.","options":["much","How much","How many","lot"]},{"id":"v35-g6t2-0-11","prompt":"How ___ milk is left?","answer":"much","why":"Неисчисляемое milk.","options":["How many","many","much","How much"]},{"id":"v35-g6t2-0-12","prompt":"There isn't ___ space for another desk. (use MUCH)","answer":"much","why":"Неисчисляемое space.","options":["lot","much","How many","many"]}],[{"id":"v35-g6t2-1-1","prompt":"Correct: How much pencils do you need?","answer":"How many pencils do you need?","why":"Pencils исчисляемые.","options":null},{"id":"v35-g6t2-1-2","prompt":"Correct: Many information is available.","answer":"Much information is available.||A lot of information is available.","why":"Information неисчисляемое.","options":null},{"id":"v35-g6t2-1-3","prompt":"Rewrite using A LOT OF: She has many friends.","answer":"She has a lot of friends.","why":"A lot of со множественным числом.","options":null},{"id":"v35-g6t2-1-4","prompt":"Rewrite using HOW MUCH: What quantity of water do we need?","answer":"How much water do we need?","why":"Water неисчисляемое.","options":null},{"id":"v35-g6t2-1-5","prompt":"Correct: How many money do you have?","answer":"How much money do you have?","why":"Money неисчисляемое.","options":null},{"id":"v35-g6t2-1-6","prompt":"Make a question using HOW MANY: There are ten chairs.","answer":"How many chairs are there?","why":"How many + chairs.","options":null},{"id":"v35-g6t2-1-7","prompt":"Correct: A lot people came.","answer":"A lot of people came.","why":"Перед существительным нужно of.","options":null},{"id":"v35-g6t2-1-8","prompt":"Rewrite with MUCH: We have very little time. [negative statement: no large amount]","answer":"We don't have much time.","why":"Much с неисчисляемым в отрицании.","options":null},{"id":"v35-g6t2-1-9","prompt":"Correct: I study a lot of. [no noun follows]","answer":"I study a lot.","why":"Наречная фраза a lot без of.","options":null},{"id":"v35-g6t2-1-10","prompt":"Correct: There is many luggage in the car.","answer":"There is a lot of luggage in the car.||There is much luggage in the car.","why":"Luggage неисчисляемое.","options":null},{"id":"v35-g6t2-1-11","prompt":"Make a question using HOW MUCH: We need five kilos of rice.","answer":"How much rice do we need?","why":"Rice как масса.","options":null},{"id":"v35-g6t2-1-12","prompt":"Rewrite with MANY: There are a lot of problems.","answer":"There are many problems.","why":"Problems исчисляемые.","options":null}],[{"id":"v35-g6t2-2-1","prompt":"How ___ (MANY) questions did the pupils answer?","answer":"many","why":"Questions — множественное исчисляемое.","options":null},{"id":"v35-g6t2-2-2","prompt":"How ___ (MUCH) advice did the counsellor give?","answer":"much","why":"Advice — неисчисляемое.","options":null},{"id":"v35-g6t2-2-3","prompt":"The school library has a ___ (LOT) of new books.","answer":"lot","why":"A lot of books.","options":null},{"id":"v35-g6t2-2-4","prompt":"We don't have ___ (MUCH) information yet.","answer":"much","why":"Неисчисляемое, отрицание.","options":null},{"id":"v35-g6t2-2-5","prompt":"The volunteers brought ___ (MANY) boxes of food.","answer":"many","why":"Boxes можно посчитать.","options":null},{"id":"v35-g6t2-2-6","prompt":"How ___ (MUCH) homework did they get?","answer":"much","why":"Homework неисчисляемое.","options":null},{"id":"v35-g6t2-2-7","prompt":"There were a ___ (LOT) of people outside the stadium.","answer":"lot","why":"A lot of people.","options":null},{"id":"v35-g6t2-2-8","prompt":"___ (HOW MANY) students took the bus? [write 2 words]","answer":"How many","why":"Вопрос об исчисляемом количестве.","options":null},{"id":"v35-g6t2-2-9","prompt":"___ (HOW MUCH) time did the journey take? [write 2 words]","answer":"How much","why":"Time неисчисляемое.","options":null},{"id":"v35-g6t2-2-10","prompt":"We spent a ___ (LOT) of money on repairs.","answer":"lot","why":"A lot of money.","options":null},{"id":"v35-g6t2-2-11","prompt":"The museum doesn't have ___ (MANY) visitors in winter.","answer":"many","why":"Visitors исчисляемое.","options":null},{"id":"v35-g6t2-2-12","prompt":"There isn't ___ (MUCH) space in the suitcase.","answer":"much","why":"Space неисчисляемое.","options":null}]]},"Some / any / no":{"slug":"g6t3","theory":"<article class=\"gm35 gm35-topic-11\" id=\"rule-theory\" lang=\"ru\"><header><small>ОПРЕДЕЛИТЕЛИ · ОЖИДАНИЕ И ОТРИЦАНИЕ</small><h2>Some, any, no: важен не только знак вопроса</h2><p>Школьная памятка «some — утверждение, any — вопрос» помогает начать, но <b>не объясняет</b> предложения с предложением помощи, просьбой, условием и словами any = «любой».</p></header>\n<section><h3>Три исходные ситуации</h3><div class=\"gm35-grid\"><article><b>Some: есть часть</b><p>There is <b>some milk</b>. — Молоко есть.</p></article><article><b>Any: неизвестно / сколько-нибудь</b><p>Is there <b>any milk</b>? — Есть ли молоко?</p></article><article><b>No: количество равно нулю</b><p>There is <b>no milk</b>. — Молока нет.</p></article></div><p>Не делай двойное отрицание: <b>There isn't any milk</b> = <b>There is no milk</b>, но <s>There isn't no milk</s> неверно в стандартном экзаменационном английском.</p></section>\n<section><h3>Когда some употребляется в вопросе?</h3><p><b>Would you like some tea?</b> — Хочешь чаю? (предложение). <b>Could I have some water?</b> — Можно мне воды? (просьба). Говорящий предполагает возможное положительное согласие или предлагает конкретную порцию.</p><p><b>Any</b> в утверждении нередко означает «любой»: You can choose <b>any book</b>. — Можешь выбрать любую книгу. В условии: If you have <b>any questions</b>, ask me. — Если появятся какие-либо вопросы, спроси.</p></section>\n<section><h3>Формы и тип существительного</h3><div class=\"gm35-table\"><table><tr><th>Исчисляемое мн. ч.</th><th>Неисчисляемое</th></tr><tr><td>some apples / any apples / no apples</td><td>some money / any money / no money</td></tr></table></div><div class=\"gm35-error\"><s>I don't have no time.</s><b>I don't have any time. / I have no time.</b><small>В стандартной письменной речи — одно грамматическое отрицание.</small></div><div class=\"gm35-error\"><s>Would you like any coffee? [предлагаем кофе]</s><b>Would you like some coffee?</b><small>В обычном предложении напитка natural some.</small></div><p>В каждом задании смотри на <b>намерение говорящего</b>, а не только на вопросительный знак.</p></section></article>","levels":[[{"id":"v35-g6t3-0-1","prompt":"There are ___ oranges in the basket. (affirmative; some oranges are present)","answer":"some","why":"Некоторое количество.","options":["some","any","no"]},{"id":"v35-g6t3-0-2","prompt":"Is there ___ milk in the fridge? (neutral question, no expectation)","answer":"any","why":"Нейтральный вопрос.","options":["no","some","any"]},{"id":"v35-g6t3-0-3","prompt":"We have ___ money left. (zero; use NO)","answer":"no","why":"No + noun = ноль.","options":["any","no","some"]},{"id":"v35-g6t3-0-4","prompt":"Would you like ___ tea? (offer)","answer":"some","why":"Some естественно в предложении.","options":["some","no","any"]},{"id":"v35-g6t3-0-5","prompt":"I don't have ___ questions.","answer":"any","why":"Отрицание + any.","options":["some","no","any"]},{"id":"v35-g6t3-0-6","prompt":"You can take ___ book from this shelf. (whichever you want)","answer":"any","why":"Any = любой.","options":["some","any","no"]},{"id":"v35-g6t3-0-7","prompt":"Could I have ___ water? (request)","answer":"some","why":"Просьба о количестве воды.","options":["some","any","no"]},{"id":"v35-g6t3-0-8","prompt":"There is ___ sugar in my coffee. (zero; use NO)","answer":"no","why":"Отрицательный определитель.","options":["any","some","no"]},{"id":"v35-g6t3-0-9","prompt":"Do you have ___ plans this weekend?","answer":"any","why":"Нейтральный вопрос.","options":["no","any","some"]},{"id":"v35-g6t3-0-10","prompt":"I bought ___ apples and pears. (affirmative; some fruit was purchased)","answer":"some","why":"Утвердительное.","options":["some","no","any"]},{"id":"v35-g6t3-0-11","prompt":"If you find ___ mistakes, tell me.","answer":"any","why":"Any в условии.","options":["some","no","any"]},{"id":"v35-g6t3-0-12","prompt":"There aren't ___ tickets available.","answer":"any","why":"Отрицание + any.","options":["some","any","no"]}],[{"id":"v35-g6t3-1-1","prompt":"Correct: I haven't got no time.","answer":"I haven't got any time.","why":"Одно грамматическое отрицание.","options":null},{"id":"v35-g6t3-1-2","prompt":"Rewrite with NO: There isn't any bread.","answer":"There is no bread.","why":"No + существительное.","options":null},{"id":"v35-g6t3-1-3","prompt":"Rewrite with ANY: I have no questions.","answer":"I don't have any questions.","why":"Don't + any.","options":null},{"id":"v35-g6t3-1-4","prompt":"Rewrite a natural neutral offer with SOME: Would you like any coffee?","answer":"Would you like some coffee?","why":"В предложениях обычно some.","options":null},{"id":"v35-g6t3-1-5","prompt":"Correct: There isn't some water left.","answer":"There isn't any water left.","why":"Отрицание + any.","options":null},{"id":"v35-g6t3-1-6","prompt":"Rewrite with ANY = whichever: Choose a book; it doesn't matter which.","answer":"Choose any book.","why":"Any в утверждении = любой.","options":null},{"id":"v35-g6t3-1-7","prompt":"Correct: I have not no idea.","answer":"I have no idea.","why":"Одно отрицание.","options":null},{"id":"v35-g6t3-1-8","prompt":"Rewrite with SOME: Please give me water. [polite request]","answer":"Could I have some water, please?","why":"Просьба, поэтому some.","options":null},{"id":"v35-g6t3-1-9","prompt":"Correct: She didn't buy no apples.","answer":"She didn't buy any apples.","why":"Стандартное отрицание + any.","options":null},{"id":"v35-g6t3-1-10","prompt":"Make a question: There are some seats left.","answer":"Are there any seats left?","why":"Нейтральный вопрос + any.","options":null},{"id":"v35-g6t3-1-11","prompt":"Rewrite using NO: There aren't any buses today.","answer":"There are no buses today.","why":"Нет ни одного автобуса.","options":null},{"id":"v35-g6t3-1-12","prompt":"Rewrite with ANY: If you have some problems, call us. [open condition]","answer":"If you have any problems, call us.","why":"Any подходит в открытом условии.","options":null}],[{"id":"v35-g6t3-2-1","prompt":"I didn't see ___ (ANY) errors in the report.","answer":"any","why":"Отрицание.","options":null},{"id":"v35-g6t3-2-2","prompt":"There were ___ (SOME) friendly people on the train.","answer":"some","why":"Утверждение.","options":null},{"id":"v35-g6t3-2-3","prompt":"Would you like ___ (SOME) cake?","answer":"some","why":"Предложение угощения.","options":null},{"id":"v35-g6t3-2-4","prompt":"Are there ___ (ANY) free seats in this carriage?","answer":"any","why":"Вопрос.","options":null},{"id":"v35-g6t3-2-5","prompt":"We had ___ (NO) information about the delay.","answer":"no","why":"Нулевое количество.","options":null},{"id":"v35-g6t3-2-6","prompt":"If you need ___ (ANY) help, contact the office.","answer":"any","why":"Условное предложение.","options":null},{"id":"v35-g6t3-2-7","prompt":"You may choose ___ (ANY) colour you like.","answer":"any","why":"Любой из вариантов.","options":null},{"id":"v35-g6t3-2-8","prompt":"Could I have ___ (SOME) extra time, please?","answer":"some","why":"Вежливая просьба.","options":null},{"id":"v35-g6t3-2-9","prompt":"The guide showed us ___ (SOME) unusual places.","answer":"some","why":"Утвердительное.","options":null},{"id":"v35-g6t3-2-10","prompt":"There wasn't ___ (ANY) fresh bread in the shop.","answer":"any","why":"Отрицание.","options":null},{"id":"v35-g6t3-2-11","prompt":"We received ___ (NO) reply to our email.","answer":"no","why":"Не получили ответа.","options":null},{"id":"v35-g6t3-2-12","prompt":"Do you have ___ (ANY) suggestions for the project?","answer":"any","why":"Нейтральный вопрос.","options":null}]]},"Few / a few / little / a little":{"slug":"g6t4","theory":"<article class=\"gm35 gm35-topic-12\" id=\"rule-theory\" lang=\"ru\"><header><small>КОЛИЧЕСТВО · ОЦЕНКА ДОСТАТОЧНОСТИ</small><h2>Few / a few / little / a little: почему артикль a меняет оценку?</h2><p>Все четыре выражения могут обозначать небольшое количество. Но без <b>a</b> говорящий обычно подчёркивает <b>нехватку</b>, а с <b>a</b> — наличие некоторого запаса.</p></header>\n<section><h3>Две независимые оси</h3><div class=\"gm35-table\"><table><tr><th></th><th>Мало, недостаточно</th><th>Немного, но есть</th></tr><tr><td>Исчисляемое мн. ч.</td><td><b>few friends</b><small>Почти нет друзей.</small></td><td><b>a few friends</b><small>Есть несколько друзей.</small></td></tr><tr><td>Неисчисляемое</td><td><b>little time</b><small>Времени почти нет.</small></td><td><b>a little time</b><small>Немного времени есть.</small></td></tr></table></div><p>«Few» и «little» не обозначают строгое число или объём: оценка зависит от ситуации.</p></section>\n<section><h3>Смысл изменяется из-за одного a</h3><div class=\"gm35-grid two\"><article><b>Проблема</b><p>We have <b>little time</b>; hurry up! — Времени почти нет; поторопись!</p><p>There are <b>few buses</b> at night. — Ночью автобусов мало.</p></article><article><b>Возможность</b><p>We have <b>a little time</b>; let's talk. — У нас есть немного времени; поговорим.</p><p>There are <b>a few buses</b> after midnight. — После полуночи ещё есть несколько автобусов.</p></article></div><p><b>Only a few / only a little</b> подчёркивают ограниченное количество, даже с a: Only a few people came. — Пришло всего несколько человек.</p></section>\n<section><h3>Нельзя механически заменить на less/fewer</h3><p><b>Fewer</b> — сравнительная степень от few, используется с исчисляемыми: fewer mistakes (меньше ошибок). <b>Less</b> — с неисчисляемыми: less noise (меньше шума). В контрольных задачах не смешивай «мало» (few/little) и «меньше» (fewer/less).</p><div class=\"gm35-error\"><s>I have a few money.</s><b>I have a little money.</b><small>Money — неисчисляемое.</small></div><div class=\"gm35-error\"><s>There are little students today.</s><b>There are few students today.</b><small>Students — исчисляемое множественное.</small></div></section></article>","levels":[[{"id":"v35-g6t4-0-1","prompt":"I have ___ friends here, so I feel lonely. (countable, shortage)","answer":"few","why":"Few = мало, нехватка.","options":["few","a few","little","a little"]},{"id":"v35-g6t4-0-2","prompt":"We have ___ minutes to talk before the bus arrives. (some time available)","answer":"a few","why":"A few + исчисляемые.","options":["little","a little","Few","a few"]},{"id":"v35-g6t4-0-3","prompt":"There is ___ water left; we're nearly out. (shortage)","answer":"little","why":"Little + неисчисляемое.","options":["Few","few","little","a little"]},{"id":"v35-g6t4-0-4","prompt":"I have ___ money, enough for a snack. (some available)","answer":"a little","why":"A little + money.","options":["a few","a little","Few","few"]},{"id":"v35-g6t4-0-5","prompt":"Only ___ students attended the optional lecture.","answer":"a few","why":"Only a few = всего несколько.","options":["a few","few","little","a little"]},{"id":"v35-g6t4-0-6","prompt":"They made ___ mistakes, so their work was nearly perfect. (use A FEW)","answer":"a few","why":"Некоторое небольшое число ошибок.","options":["little","a little","Few","a few"]},{"id":"v35-g6t4-0-7","prompt":"There were ___ buses at night, so we had to walk. (shortage)","answer":"few","why":"Нехватка автобусов.","options":["little","a little","few","a few"]},{"id":"v35-g6t4-0-8","prompt":"Can you wait ___ minutes? (several)","answer":"a few","why":"Countable minutes.","options":["little","a few","Few","few"]},{"id":"v35-g6t4-0-9","prompt":"We have ___ time; hurry up! (almost none)","answer":"little","why":"Little time.","options":["little","few","a few","a little"]},{"id":"v35-g6t4-0-10","prompt":"She speaks ___ German, enough to order food.","answer":"a little","why":"A little + неисчисляемый язык как количество знания.","options":["a few","little","Few","a little"]},{"id":"v35-g6t4-0-11","prompt":"There are ___ seats left; most people will have to stand. (almost none)","answer":"few","why":"Нехватка мест.","options":["a little","a few","few","little"]},{"id":"v35-g6t4-0-12","prompt":"Add ___ salt, but not too much.","answer":"a little","why":"A little + неисчисляемое.","options":["a few","a little","Few","few"]}],[{"id":"v35-g6t4-1-1","prompt":"Correct: I have a few money.","answer":"I have a little money.","why":"Money неисчисляемое.","options":null},{"id":"v35-g6t4-1-2","prompt":"Correct: There are little people here. [meaning: not many people, not short people]","answer":"There are few people here.","why":"People исчисляемое множественное.","options":null},{"id":"v35-g6t4-1-3","prompt":"Rewrite showing POSITIVE availability: We have little time to rest.","answer":"We have a little time to rest.","why":"Артикль a меняет оценку с нехватки на наличие.","options":null},{"id":"v35-g6t4-1-4","prompt":"Rewrite showing SHORTAGE: There are a few buses at night.","answer":"There are few buses at night.","why":"Без a подчёркивается нехватка.","options":null},{"id":"v35-g6t4-1-5","prompt":"Correct: She has few experience.","answer":"She has little experience.","why":"Experience как опыт неисчисляемое.","options":null},{"id":"v35-g6t4-1-6","prompt":"Correct: He speaks a few Italian.","answer":"He speaks a little Italian.","why":"Язык в значении объёма знания.","options":null},{"id":"v35-g6t4-1-7","prompt":"Rewrite with A FEW: We have several friends here.","answer":"We have a few friends here.","why":"Некоторое число друзей.","options":null},{"id":"v35-g6t4-1-8","prompt":"Rewrite with A LITTLE: There is some milk left.","answer":"There is a little milk left.","why":"Немного молока есть.","options":null},{"id":"v35-g6t4-1-9","prompt":"Correct: I have little books.","answer":"I have few books.","why":"Books исчисляемые.","options":null},{"id":"v35-g6t4-1-10","prompt":"Correct: We need a little chairs.","answer":"We need a few chairs.","why":"Chairs исчисляемые.","options":null},{"id":"v35-g6t4-1-11","prompt":"Rewrite negative evaluation: We still have a little money.","answer":"We have little money.","why":"Нет артикля — подчёркивается нехватка.","options":null},{"id":"v35-g6t4-1-12","prompt":"Correct: She made a little mistakes.","answer":"She made a few mistakes.","why":"Mistakes исчисляемые.","options":null}],[{"id":"v35-g6t4-2-1","prompt":"The village has ___ (FEW) shops, so people drive to town. [shortage]","answer":"few","why":"Мало магазинов, нехватка.","options":null},{"id":"v35-g6t4-2-2","prompt":"We still have ___ (A LITTLE) time before the film starts. [2 words]","answer":"a little","why":"Некоторое время осталось.","options":null},{"id":"v35-g6t4-2-3","prompt":"At the meeting, only ___ (A FEW) people asked questions. [2 words]","answer":"a few","why":"Only a few — всего несколько.","options":null},{"id":"v35-g6t4-2-4","prompt":"We have ___ (LITTLE) information about the event; it's hard to plan.","answer":"little","why":"Почти нет информации.","options":null},{"id":"v35-g6t4-2-5","prompt":"The student made ___ (A FEW) spelling mistakes but answered correctly. [2 words]","answer":"a few","why":"Немного ошибок было.","options":null},{"id":"v35-g6t4-2-6","prompt":"There is ___ (LITTLE) milk, so we should go shopping.","answer":"little","why":"Нехватка молока.","options":null},{"id":"v35-g6t4-2-7","prompt":"Add ___ (A LITTLE) sugar if the tea tastes bitter. [2 words]","answer":"a little","why":"Небольшое количество сахара.","options":null},{"id":"v35-g6t4-2-8","prompt":"___ (FEW) tourists visit the island in winter.","answer":"Few","why":"Недостаточно туристов.","options":null},{"id":"v35-g6t4-2-9","prompt":"We bought ___ (A FEW) postcards for our friends. [2 words]","answer":"a few","why":"Несколько отдельных открыток.","options":null},{"id":"v35-g6t4-2-10","prompt":"I know ___ (A LITTLE) about astronomy; I can explain the basics. [2 words]","answer":"a little","why":"Небольшой запас знаний.","options":null},{"id":"v35-g6t4-2-11","prompt":"There is ___ (LITTLE) space in the bag, so the coat won't fit.","answer":"little","why":"Недостаток пространства.","options":null},{"id":"v35-g6t4-2-12","prompt":"We had ___ (A FEW) problems, but we solved them all. [2 words]","answer":"a few","why":"Некоторые проблемы были, но их решено.","options":null}]]}};
 const titles=new Set(program.grammarGroups.flatMap(group=>group.topics.map(topic=>topic.title)));
 // Make the update atomic: no partial replacement if a topic or task bank fails validation.
 for(const [title,chapter] of Object.entries(chapters)){
  if(!titles.has(title)||!reference.guides[title]){console.error('v35: unknown topic',title);return;}
  if(chapter.levels.length!==3||chapter.levels.some(level=>level.length!==12)){console.error('v35: incomplete bank',title);return;}
 }
 for(const [title,chapter] of Object.entries(chapters)){
  reference.guides[title]={...reference.guides[title],theory:chapter.theory,levels:chapter.levels,v35:true};
 }
 window.OGE_GRAMMAR_INDIVIDUAL_V35={installed:Object.keys(chapters).length,topics:Object.keys(chapters),bankSize:432};
})();
